INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `VerifiedBuild`) VALUES
(8479, 'itIT', 'Zul''marosh', 0)
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Details`, `VerifiedBuild`) VALUES
(2755, 'itIT', 'Orokk non piange, $N. Fuliggine negli occhi.$B$B<Orokk si asciuga una lacrima.>$B$BC''è un ultimo segreto della famiglia Omosh che Orokk t''insegnerà. Orokk morirà felice grazie a te, $N.$B$BImpara la Danza della Gioia Omosh e imparerai a realizzare il pugno di ferro!', 0),
(7937, 'itIT', '"La tua fortuna ti attende a Vallevante".$B$B<Il biglietto della fortuna che ti ha consegnato Sayge è leggermente tiepido al tocco. Stringendolo, vedi un''immagine del Campo di Taglio di Vallevante, nella Foresta di Elwynn. Guardando più attentamente l''immagine, scorgi un covone accanto a una stalla.>', 0),
(7944, 'itIT', '"La tua fortuna ti attende all''interno della Caverna dei Lamenti".$B$B<Il biglietto della fortuna che ti ha consegnato Sayge è leggermente tiepido al tocco. Stringendolo, vedi un''immagine di una caverna nella parte sudoccidentale del Crocevia, nelle Savane. Guardando più attentamente l''immagine, noti una serie di passaggi tortuosi che termina davanti a un portale luminoso, che conduce nel cuore della caverna stessa. Entrandoci, dal nulla appare uno strano forziere.>', 0),
(7945, 'itIT', '"La tua fortuna ti attende fuori la Roccia dei Mantopallido".$B$B<Il biglietto della fortuna che ti ha consegnato Sayge è leggermente tiepido al tocco. Stringendolo, vedi un''immagine della Roccia dei Mantopallido a Mulgore. Guardando più attentamente l''immagine, scorgi un ceppo accanto all''ingresso della caverna.>', 0),
(8470, 'itIT', '<Hai trovato uno dei Totem Rituale dei Mezzorsi Legnomorto. Il totem di per sé non sembra diverso dagli altri, ma emana un senso di disperazione. Esso simboleggia perfettamente la corruzione che ha colpito i Mezzorsi Legnomorto.>$B$B<Uno dei Mezzorsi all''interno del Rifugio dei Mordilegno potrebbe essere interessato a questo oggetto... sempre che riuscirai a convincerlo ad ascoltarti.>', 0),
(9026, 'itIT', 'Dobbiamo rintracciare l''origine. Ho notato più gente del previsto entrare e uscire dalla Rosa Dorata. Guardie incluse. Parla con Allison. Se è lei a venderli, potrà dirti da dove provengono.', 0),
(9544, 'itIT', '<Le immagini su questo totem raffigurano la guerra tra la tribù dei Mezzorsi Pinosaldo e quella dei Mezzorsi Braccioirsuto. Le incisioni mostrano come i Braccioirsuto abbiano agito senza alcuno scrupolo nei confronti dei Pinosaldo.>$B$B<Nel caos della guerra prese forma una profezia: un giorno sarebbe giunto un eroe non Mezzorso a salvare la Tribù Pinosaldo.>$B$B<Uccidi i Mezzorsi Braccioirsuto al Villaggio dei Braccioirsuto e recupera le loro chiavi. Usa le chiavi per liberare i Prigionieri Pinosaldo. Dopo averli liberati tutti, torna da Arugoo dei Pinosaldo!>', 0),
(9566, 'itIT', '<A giudicare dalla superficie, il cristallo sembra essere un componente della Exodar. Tuttavia, qualcosa dev''essere andato terribilmente storto con questo cristallo, poiché è rosso sangue e si dissolve rapidamente nella faglia acquifera della caverna.>$B$B<Questo potrebbe spiegare il comportamento insolitamente aggressivo delle creature di Brumazzurra. Torna dal Gran Capo Pinosaldo e riferiscigli quanto scoperto.>', 0),
(9819, 'itIT', 'Scopri usurpatore. Lo troverai. Segui sentiero della terra. Prima dai pace agli Spiriti Torturati della Terra. Devo tornare a dormire.$B$B<Gordag colpisce il terreno con il pugno e prende della terra dall''odore fetido.>$B$BDevo dormire!$B$B<Gordag punta verso sud-est.>$B$BTrova spiriti vicino alle montagne. Vicino alle colline. Vicino alle rocce. Vicino alla terra.$B$BMettili a dormire.$B$BBacino di Telaar... Sud-est.', 0),
(9871, 'itIT', '<La cartapecora riporta una rozza mappa di Nagrand. C''è una grossa X rossa dove dovrebbe trovarsi Telaar. Sembra che quei selvaggi intendano attaccare la città. Porta i piani d''invasione dei Sanguebuio ad Arechron a Telaar.>', 0),
(9924, 'itIT', '<Arechron sospira.>$B$BÈ davvero imbarazzante. Ti ricordi mio figlio, Corki? Di recente l''hai salvato dalle Rovine delle Lame Ardenti. Ecco, si è fatto prendere ancora dalla curiosità. Mi ha detto che avrebbe indagato sulla minaccia dei Rocciadura per conto dello "zio" Mo''mor ed è corso via verso il Tumulo degli Ogre nel Bacino di Halaa, a nord di qui.$B$BTi spiacerebbe rintracciarlo? Te ne sarei eternamente grato.', 0),
(9933, 'itIT', '<Lantresor indica una cassa anonima.>$B$BPrendila. È la mia offerta per la tua gente. Hai salvato senza alcun aiuto il mio clan dallo sterminio.$B$BPuoi dire al tuo capo che Lantresor della Lama e i suoi Ogre Rocciadura accettano l''offerta di pace.$B$B<Lantresor s''inchina.>', 0),
(10010, 'itIT', '<Sal''salabim indica il progetto.>$B$BVedi dove Vilcannoni sono?$B$B<Sal''salabim traccia una freccia che punta in direzione opposta.>$B$BTu giri Cannoni e usa su strutture.$B$BAspetta! Non arrabbiarti! Una cosa non sa. Responsabili hanno chiave per girare cannoni. Ti serve chiave prima! Una da ogni sovrintendente!$B$BNon Così facile, eh?$B$BDai informazioni ad Altruis.', 0),
(10395, 'itIT', '<I caratteri usati per scrivere questa annotazione sono degli scarabocchi oscuri e incomprensibili. Più li fissi, più sembrano contorcersi e bruciare davanti ai tuoi occhi. In tutta la Rocca dell''Onore, solo una persona può decifrare queste scritte arcaiche: Kryv, il mistico dei Draenei.>$B$B<Porta la Lettera della Legione Infuocata al Veggente Distorcente Kryv nella Sala della Guerra della Rocca dell''Onore.>', 0),
(10672, 'itIT', 'Dobbiamo approfondire gli studi su queste creature.$B$BMolto a est, vicino agli enormi flussi di lava sotto le Rovine di Baa''ri, troverai delle Unità di Controllo Arcano. Sono state create da un genio di nome Gnomus con il solo scopo di esplorare la lava con scorpioni meccanici.$B$BDa tempo ha perso il senno e ora è interessato solo a mangiare le pietanze più calde e piccanti conosciute dagli Gnomi.$B$B<Tiorus fa un''espressione divertita.>$B$BVoglio usare i Controlli e marcare i Diemetradonti del flusso di lava per approfondire gli studi.', 0),
(10883, 'itIT', '$N, hai dimostrato di essere capace di compiere grandi imprese. La tua scoperta del Cifrario della Dannazione e del coinvolgimento di Kael''thas è molto importante per la nostra causa. Se Kael dovesse usare il Cifrario, ciò che resta del mondo potrebbe collassare.$B$BA''dal è convito che Kael debba essere fermato e cerca avventurieri da sottoporre a delle prove. Chi dimostrerà la propria forza, otterrà i favori dei Naaru.$B$B<Khadgar annuisce.>$B$BA''dal attende...', 0),
(11100, 'itIT', 'Le Fauci di Drago osano attaccarci solo quando abbiamo la guardia abbassata. Perirebbero sicuramente se ci assalissero quando siamo preparati.$B$BVoglio che tu li lasci venire a noi, $N.$B$B<Ceyla annuisce.>$B$BSì... una trappola. Prendi questa spararazzi che ti ha dato il loro Supremo e consegnala al Comandante Arcus. È di guardia proprio fuori da questo edificio.', 0),
(11288, 'itIT', '<Ad Ares manca il fiato, mentre tenta di parlare.>$B$BSono un inviato della Crociata d''Argento, incaricato di portare a termine una missione sacra.$B$BLe nostre forze sono state decimate nelle Terre Infette. Prima che sorgesse l''alba, il manufatto era stato nuovamente purificato. Molti sono morti per la sua redenzione.$B$BC''è ancora una speranza... c''è ancora tempo.$B$BIl Manufatto è stato gettato nell''antro dei caduti, molto al di sotto di noi, ed è sorvegliato da morti spietati.$B$B<Il corpo di Ares risplende di un bagliore accecante.>$B$BLa... Luce... ti... proteggerà.', 0),
(11611, 'itIT', '<Mortuus sospira.>$B$BI Peoni... Tanto vale piantare un cartello con su scritto "Pasti gratis per i Nerub''ar".$B$BVedi, il problema con i Peoni è che: (1) sono più stupidi del fango e (2) sono più deboli di uno Gnomo Contaminato. Non c''è da sorprendersi, perciò, se sono i primi a essere catturati dal Flagello!$B$BQuesto, però, mi mette in una situazione poco invidiabile: senza Peoni, il lavoro manuale si ferma. Niente Peoni, niente costruzioni.$B$BTrova e libera i miei Peoni, $r. Se sono ancora vivi, li troverai avvolti in ragnatele nella Cava di Pietragrossa.', 0),
(11711, 'itIT', 'Ogni giorno che passa, dinanzi ai nostri cancelli riceviamo sempre più disertori nemici. Semplicemente non sappiamo più dove sistemare tutti questi vermi da prigionia, specialmente se vogliamo anche garantire loro delle condizioni decenti.$B$B<Nork ride e sbuffa.>$B$BVorrei che scortassi uno di questi codardi all''incrocio a est e poi usassi questa spararazzi. Quando vedrà la segnalazione, uno dei suoi Capitani verrà a prendersi il codardo.$B$BUna volta effettuata la consegna, fai rapporto all''Esploratore Tungok sulla strada a est.', 0),
(11892, 'itIT', '$N, hai fatto molto per gli animali della Tundra Boreale. I Lacchè di Nesingwary sono stati colpiti duramente e hanno ricevuto una lezione che non dimenticheranno tanto facilmente.$B$BHarold Lane, il principale responsabile dei massacri di Nagrand, è stato identificato come l''uomo a capo delle operazioni di Nesingwary nella Tundra. In questo momento si trova al Lago Kum''uya, a ovest di qui.$B$B<Lathorius ti porge un corno di quercia finemente inciso.>$B$BTrova Lane e uccidilo. Nel caso avessi bisogno del nostro aiuto, suona questo corno.', 0),
(12056, 'itIT', 'Ho assistito al suo tradimento con i miei occhi! Il traditore ha guidato un assalto di Anub''ar contro questa roccaforte, uccidendo alcuni dei miei migliori soldati.$B$B<Gort scuote la testa.>$B$BHa lavorato per tutto il tempo con il Flagello senza che ce ne accorgessimo! Quanti altri ce ne sono là fuori come Zangus? Li troveremo tutti e daremo loro ciò che si meritano...$B$B<Gort mima il gesto di tagliare la gola.>$B$BIl primo della lista è Zangus. I nostri esploratori ci hanno riferito che si nasconde nella Fossa di Narjun, a ovest. Trovalo, uccidilo e portami la sua testa.', 0),
(12140, 'itIT', 'Come i Tauren, i Reietti, i Troll e gli Elfi del Sangue, anche i Taunka hanno bisogno di un capo che discenda dal loro stesso sangue. Questo capo sarà colui che hai salvato da Foscogelo: Roanauk.$B$B<Il Supremo Agmar ti consegna una cartapecora.>$B$BSono certo che riconoscerai il Giuramento di Sangue dell''Orda.$B$BConsegnalo a Roanauk Fosco Gelo e introducilo all''Orda come capo dei Taunka.$B$BNon facciamolo aspettare.$B$B<Agmar annuisce.>', 0),
(12174, 'itIT', '<Palena ti restituisce la lettera.>$B$BTempesta di Neve ti condurrà a Guardia Invernale, $N. Sarà il volo più rapido che tu abbia mai fatto. Ora va''!', 0),
(12181, 'itIT', 'Santo cielo, quanto tempo è passato? Da quanto lavoriamo a questa dannata pestilenza? Finalmente, dopo un''eternità di fallimenti, abbiamo raggiunto la perfezione. Questa... non ha ancora un nome! Questo morbo... Sì, ecco: MORBO! Questo Morbo farà a pezzi il tessuto stesso della vita!$B$B<Harris ti consegna una fiala.>$B$BCerca Tobias, l''Addestratore di Pipistrelli, e mostragli gli esemplari: ti manderà a Venefica.', 0),
(12298, 'itIT', '<Greer ti restituisce la lettera.>$B$BCantacielo ti condurrà a Guardia Invernale, $N. Sarà il volo più rapido che tu abbia mai fatto. Ora va''!', 0),
(12662, 'itIT', '<Dagoda guarda Ahunae e sospira.>$B$BVuoi veramente vedertela con Heb''Drakkar? Raccogliere scalpi nun è la soluzione. Devi accidere il capo loro, Heb''jin.$B$BIl problema è che campa nel suo nido di pipistrello da dove aizza le forze sue.$B$BPicchia il tamburo suo e ti assicuro che scenderà. Quindi dovrai acciderlo.$B$BPuoi pigliare chesta rete che arriva da uno dei covi suoi. Usala per catturare il pipistrello quando atterra. In chisto modo nun dovrai combatterli entrambi.', 0),
(13148, 'itIT', '<Allegato alla Collana Danneggiata c''è un documento con su scritto: "Proprietà di Timothy Jones - Gioielleria Cartier & Co. - Distretto dei Commercianti - Dalaran">.$B$B<Forse dovresti ripararla e riconsegnarla al proprietario.>', 0)
