INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(941, 'itIT', '<Metti il cuore nella fioriera, ed esso sprofonda rapidamente da solo sottoterra!>$B$B<Pochi secondi dopo vi riemerge, pulito. Pulsa leggermente... invitandoti a prenderlo.>', 0),
(1454, 'itIT', '<A quanto pare, la cassa non è stata danneggiata dall''acqua.>$B$B<La seconda cosa che ti salta all''occhio è che il coperchio è stato forzato e qualsiasi trappola magica ci fosse per difenderlo è stata attivata da tempo, come si evince dai segni delle bruciature sui bordi.>', 0),
(2278, 'itIT', '<Seguendo le indicazioni del Guardiano della Pietra, accedi ai dischi di Norgannon dopo aver appreso della storia del Terrigeno, dei Trogg e dei Nani. I dischi emettono un debolissimo ronzio. Quindi è il Guardiano della Pietra a parlare:>$B$B"I dischi sono stati sintetizzati. Toccali ancora una volta per ottenere la tua copia personale".', 0),
(2945, 'itIT', '<Metti l''anello dentro la Lavatutto 5200 e inserisci le monete d''argento nella fessura.>$B$B<La macchina produce un chiasso infernale e inizia a sobbalzare con violenza. Non puoi fare a meno di chiederti cosa ne sarà dell''anello...>$B$B<La macchina si ferma all''improvviso, emettendo un semplice "Ding!" a indicare la fine del programma. Il cestello degli oggetti si apre rivelando un pacchetto con un fiocco rosso. A quanto pare la Lavatutto 5200 sa anche incartare i regali!>', 0),
(2953, 'itIT', '<La Lavatutto 5200 si mette in moto, muovendosi avanti e indietro. All''interno, il detergente gnomico sta eliminando lo sporco dall''oggetto introdotto nella macchina.>$B$B<La Lavatutto 5200 si ferma emettendo il consueto "Ding!". Il cestello per gli oggetti si apre, rivelando un pacchetto incartato.>', 0),
(4603, 'itIT', '<La Lavatutto 5200 si mette in moto, muovendosi avanti e indietro. All''interno, il detergente gnomico sta eliminando lo sporco dall''oggetto introdotto nella macchina.>$B$B<La Lavatutto 5200 si ferma emettendo il consueto "Ding!". Il cestello per gli oggetti si apre, rivelando un pacchetto incartato.>', 0),
(4604, 'itIT', '<La Lavatutto 5200 si mette in moto, muovendosi avanti e indietro. All''interno, il detergente gnomico sta eliminando lo sporco dall''oggetto introdotto nella macchina.>$B$B<La Lavatutto 5200 si ferma emettendo il consueto "Ding!". Il cestello per gli oggetti si apre, rivelando un pacchetto incartato.>', 0),
(9390, 'itIT', '<Hai scoperto il cadavere di un giovane Paladino Draenei. È stato ucciso con un colpo alla schiena.>', 0),
(9453, 'itIT', 'Povera Diktynna... Quel Murloc le ha fatto prendere un bello spavento.$B$B<Acteon sospira.>$B$BSperiamo che guarisca presto...$B$BAllora, immagino che tu sia qui in cerca di lavoro. Be'', il lavoro è una cosa che al Presidio Azzurro non manca mai!', 0),
(9538, 'itIT', '<Il totem presenta diversi simboli primitivi. Sulla superficie distingui le incisioni di gufi, orsi, lupi e cervi.>$B$B<Noti una strana serie di simboli che sulle tue labbra formano la parola A-K-I-D-A.>', 0),
(9539, 'itIT', '<Il totem presenta diversi simboli primitivi. Sulla superficie distingui le incisioni di gufi, orsi, lupi e cervi.>$B$B<Noti una strana serie di simboli che sulle tue labbra formano la parola C-O-O.>', 0),
(9540, 'itIT', '<Il totem presenta diversi simboli primitivi. Sulla superficie distingui le incisioni di gufi, orsi, lupi e cervi.>$B$B<Noti una strana serie di simboli che sulle tue labbra formano la parola T-I-K-T-I.>', 0),
(9541, 'itIT', '<Il totem presenta diversi simboli primitivi. Sulla superficie distingui le incisioni di gufi, orsi, lupi e cervi.>$B$B<Noti una strana serie di simboli che sulle tue labbra formano la parola Y-O-R.>', 0),
(9542, 'itIT', '<Leggendo il totem, sulle tue labbra si forma la parola V-A-R-K, traducibile come "giustizia".>', 0),
(9564, 'itIT', '<Gurf sputa sulla ciocca di pelo e cerca di fissarlo su una striscia spelacchiata del suo posteriore.>$B$BPer ora mi arrangerò così! Con un po'' di fortuna, uno degli Sciamani saprà rimediare al danno.', 0),
(9565, 'itIT', '<Il Cristallo di Sangue emana un''aura evanescente che penetra nell''acqua della caverna.>', 0),
(9584, 'itIT', '<L''Araldo Mikolaas esamina il frammento di cristallo.>$B$BQuesto frammento è molto diverso dal primo campione.$B$B<L''Araldo Mikolaas alza il frammento per esaminarlo meglio.>$B$BVedi come pulsa? Inquietante. Includerò nel mio rapporto una nota sulle modifiche che gli Elfi del Sangue sembrano aver apportato al cristallo. Grazie ancora per il tuo aiuto, $N.', 0),
(9585, 'itIT', '<L''Araldo Mikolaas riceve da te l''ultimo cristallo.>$B$BE così il set è completo. Ora non rimane altro da fare che impacchettarli per bene e inviarli alla Exodar.$B$B<L''Araldo sembra lieto di aver chiuso la questione.>$B$BNon fraintendermi, $N, sono sicuro che questa ricerca tornerà utilissima, ma al momento qui abbiamo problemi più urgenti da risolvere.', 0),
(9602, 'itIT', '<L''Esarca Menelaous prende la lettera e comincia a leggerla.>$B$BDannati... Che il Fatuo se li prenda! Una spia osservava tutto ciò che facevamo! E chissà da quanto tempo!$B$BLo riferirò subito a Velen!$B$BCi hai reso un grande servizio, $N. Tieniti pronta, perché ti ricontatterò non appena il Profeta mi avrà dato istruzioni su cosa fare.', 0),
(9623, 'itIT', '<Torallius sospira.>$B$BVa bene, fammi dare un''occhiata a quegli ordini.', 0),
(9648, 'itIT', 'Be'', ti avevo avvisato, no? Spero che questo possa in qualche modo compensare le modeste sofferenze a cui potresti essere andato incontro. Non appena avrai riacquistato le forze, torna da me e forse avrò un altro incarico... funghesco per te.', 0),
(9696, 'itIT', '<Elysia legge il documento.>$B$BSe quel che c''è scritto qui corrisponde al vero, gli Elfi del Sangue hanno aperto un portale sulle Terre Esterne! Questo spiegherebbe perché sembrano non finire mai...', 0),
(9698, 'itIT', '<Velen inizia a leggere il documento.>$B$BInteressante... Questo spiega molte cose.', 0),
(9726, 'itIT', '<Gzhun''tt fa un cenno con il capo.>$B$BSiamo felici che tu ci abbia dimostrato la tua amicizia, $N. Ora che abbiamo un alleato così potente, forse i Naga ci penseranno due volte prima di infastidirci di nuovo.', 0),
(9727, 'itIT', '<Gzhun''tt fa un cenno con il capo.>$B$BSiamo felici che tu abbia consolidato la nostra amicizia, $N. Chissà se ora che hai chiarito le cose più volte, i loro attacchi immotivati contro la nostra gente cesseranno?!?', 0),
(9779, 'itIT', '<Il Vendicatore Boros esamina il documento.>$B$BÈ scritta in thalassiano. Per fortuna conosco una persona in grado di tradurla...', 0),
(9784, 'itIT', 'Eccellente. Continua a portarmi altri esemplari di piante, se ne trovi.$B$B<Questa missione è ripetibile fino alla reputazione Onorato.>', 0),
(9794, 'itIT', 'Quindi mi hai portato il responso di Timothy?$B$B<Kialon si prende un attimo per leggere la lettera, poi ride.>$B$BDice che ha tutto sotto controllo. Dice che non ha bisogno di aiuto. Avrei dovuto aspettarmelo!$B$BCerta gente non cambia mai. Guarda, si è preso anche la briga di correggermi l''ortografia.$B$B<Kialon sospira profondamente.>$B$BNon avrei dovuto spedire la lettera. Dimenticavo che lo Specialista ha sempre la situazione sotto controllo.', 0),
(9797, 'itIT', '<Anche se tenta di nasconderlo, il volto di Kroghan sembra più disteso.>$B$BEra ora che arrivassi! Be'', non sei un esercito, ma ogni $R ritenuto idoneo che sappia impugnare un''arma o lanciare un incantesimo è il benvenuto. La gente di Garadar e l''Orda sono consanguinei e noi siamo fieri di rischiare la vita per difenderla.', 0),
(9800, 'itIT', 'Per favore, non lavarti nelle sacre acque del Trono.$B$B<L''Elementalista Lo''ap solleva la pastiglia preparata con le bacche.>$B$BMettila sotto la lingua e lascia che si sciolga lentamente. Quando si sarà dissolta, riuscirai a respirare sott''acqua come se fossi all''aria aperta.', 0),
(9802, 'itIT', 'Il rallentamento nelle nascite delle specie indigene desta grande preoccupazione. L''aumento delle specie invasive può essere correlato ai disturbi dell''ecosistema. Purtroppo non ho ancora abbastanza informazioni per giungere a una conclusione.$B$B<Lauranna annota qualcosa su un diario mentre osserva gli esemplari di piante.>$B$BPrendi, $N. Potrebbero tornarti utili.$B$BSe le trovi, portami altri esemplari di piante. Li inserirò nelle mie statistiche.', 0),
(9804, 'itIT', '<L''Elementalista Lo''ap si inginocchia nell''acqua e recita una preghiera.>$B$BIl Circolo della Terra non è fiero di ciò che è stato fatto, ma era necessario per guarire la terra.', 0),
(9818, 'itIT', '<Gordag sembra annuire.>$B$BSiedi.', 0),
(9819, 'itIT', '<Gordag annuisce con approvazione.>$B$BBene. Spiriti ora dormono.', 0),
(9821, 'itIT', '<Gordag sputa la roccia masticata, ricoprendoti con una pioggia di sassi.>$B$BVeleno. Queste rocce non sono Nagrand. Sono di veleno. Distruggi rocce veleno. Trova usurpatore.', 0),
(9847, 'itIT', '<Racconti alla Veggente Janidi cos''è successo quando hai usato il totem.>$B$BLo spirito ti ha attaccato? Deve tenete n''affinità più grossa assai con i Perduti di chello che pensavo. Nun c''è modo di farmi servire senza nu grosso impegno. Devo cercare n''altra fonte di potere in chisto mondo deviato.', 0),
(9853, 'itIT', '<Gordag mastica la Testa di Terra di Gurok, quasi disintegrando la formazione rocciosa.>$B$BRegno di Gurok è finito. Elementi della terra sono liberi. Tutti a dormire. Tu ottieni ricompensa!', 0),
(9857, 'itIT', 'È una bella storia... <Tossisce> $c, come hai cacciato tutti quei maschi. Ma penso che tu possa fare di meglio. Ho qualcos''altro in mente per te.', 0),
(9862, 'itIT', 'Li hai visti controllare gli elementi? Il vento si piegava al loro volere?$B$B<Morgh appare assorto per un momento.>$B$BÈ preccupante, $N. Devo consultarmi con gli altri.$B$BTi ringraziamo per i tuoi sforzi, $N. Forse potresti tornare al tuo villaggio e scoprire se hanno altre informazioni sui Sanguebuio e i loro spregevoli obiettivi.', 0),
(9865, 'itIT', '<Faucisaure si volta verso di te.>$B$BÈ odore di sangue quello che sento? Rimpiango di non averti potuto aiutare. Quanto orgoglio devi provare. Il mio petto si gonfia solo sapendo ciò che hai fatto.$B$BCi sono altre persone come te? Da dove provieni, esistono altri eroi?', 0),
(9866, 'itIT', '<Il Chiaroveggente Corhuk fissa il terreno, perso nei suoi pensieri. Annuisce.>$B$B<Il Chiaroveggente Corhuk si asciuga una lacrima.>$B$BCome il padre, così è il figlio... Che gli spiriti abbiano pietà di coloro che gli sbarreranno la strada.', 0),
(9874, 'itIT', '<Otonbu sospira.>$B$BQuesto ci farà tornare indietro di 10 anni nei trattati di pace con gli Orchi. Almeno, saremo ancora vivi, fatto molto positivo rispetto a quello che sarebbe successo se avessi lasciato putrefare i cadaveri.', 0),
(9888, 'itIT', '<Kilrath parla sottovoce.>$B$BQuesti Ogre sono molto particolari. Sono anche molto stupidi. Guarda come quello grasso fa ballare quello, ehm, meno grasso. È affascinante.', 0),
(9905, 'itIT', '<Maktu fa un cenno di approvazione.>$B$BMaktu ti ringrazia per l''aiuto. L''orgoglio di Maktu è appagato. Non si farà più trovare con la guardia abbassata.', 0),
(9934, 'itIT', '<Garrosh calcia via la cassa.>$B$BSprechi il tuo tempo, $R. Prendi quello che vuoi dalla cassa. Questi inutili gingilli non interessano né a me né a Garadar.', 0),
(9951, 'itIT', 'È meglio così, davvero. Se non si è in grado di accettare educatamente un invito allora non c''è niente da fare.$B$B<Il Custode Ramos sembra confuso.>$B$BChi sei e che ci fai qui? Vattene subito prima che sia troppo tardi!', 0),
(9998, 'itIT', '<L''Alto Elfo accenna di sì col capo.>$B$BÈ un buon inizio, ma Bertelm ha fatto bene a mandarti da me. Ho scoperto una cosa che potrebbe spiegare la presenza dei Vilorchi.', 0),
(10002, 'itIT', '<Theloria ti fa un cenno con la testa.>$B$BBen fatto, ci hai permesso di guadagnare un po'' di tempo. Gli Elfi del Sangue saranno curiosi di capire cos''è successo alla loro amica. Per allora, spero, avremo compreso meglio le loro intenzioni.', 0),
(10012, 'itIT', '<Bertelm prende i piani e li esamina.>$B$BSe non avessi portato questa mappa, avrei detto che eri fuori di senno. Ma questa è una prova inconfutabile. Non solo i Vilorchi sono al servizio degli Elfi del Sangue, ma a quanto pare hanno ricevuto l''ordine di tenerci occupati.$B$BQuesta mappa solleva più domande di quanto non fornisca risposte, ma almeno abbiamo un''idea più chiara di cosa stiamo affrontando qui.', 0),
(10016, 'itIT', 'Ah, ottimo lavoro. Sono ancora più belle di quanto pensassi, ci farò un ottimo mantello.$B$B<Bertelm lancia uno sguardo verso la locanda.>$B$BSì, uno splendido mantello.', 0),
(10026, 'itIT', '<Andarl si tampona la fronte con la manica della sua tunica.>$B$BGrazie al cielo. Iniziavo a temere che quelle bestie avessero preso il posto di tutte le altre creature della foresta.', 0),
(10027, 'itIT', 'Keb''ezil è contento che tu abbia risolto quel problemino, vero, Keb?$B$B<L''Imp ignora il suo padrone, probabilmente indignato.>$B$BDevi perdonare la sua maleducazione. Sai come sono questi demoni...', 0),
(10030, 'itIT', 'Ottimo, proprio quello di cui avevo bisogno... altre ossa.$B$B<Ramdor sospira.>$B$BSì, sì... non temere, farò in modo che questi resti dei nostri onorevoli antenati siano sepolti come si conviene.$B$BSe vuoi davvero aiutare i defunti, c''è qualcos''altro che puoi fare.', 0),
(10033, 'itIT', 'Già, sono certa che hai ucciso tutti quegli Sferzaossa. È ovvio, dal momento che il Capitano su quel manifesto ti ha chiesto di fornirne una prova.$B$B<Taela ti getta un''occhiata sarcastica.>$B$BTi voglio credere sulla parola. Non so chi ho fatto infuriare con questo incarico, ma ti ringrazio per il tuo impegno a sostegno dell''Alleanza. Ecco una piccola ricompensa per te.', 0),
(10058, 'itIT', 'È davvero lui? Non riesco a credere che sia sopravvissuto alla battaglia. La permanenza nelle rovine l''ha sciupato un po'', ma sono comunque felice di riaverlo.$B$BÈ l''unico ricordo tangibile che mi resta di Turalyon.$B$B<Padre Devidicus si sforza per trattenere le lacrime.>$B$BQuando combatti a fianco di una persona per così tanti anni, diventa persino più intima della tua famiglia.', 0),
(10160, 'itIT', '<Il Tenente Amadi annuisce.>$B$BBene. Ci serve tutto l''aiuto possibile. L''aumento del numero di Orchi intorno al Bastione Meridionale mi preoccupa. Ho inviato un esploratore in avanscoperta, ma non è ancora tornato.', 0),
(10185, 'itIT', '<Il Custode sembra sconsolato.>$B$BVedo già all''orizzonte la prossima ondata che arriva. Per il momento è sufficiente controllare il loro numero, ma dovremo adottare misure più definitive.', 0),
(10192, 'itIT', '<L''immagine dell''Arcimago Vargoth sembra esaminare il Compendio.>$B$BÈ un po'' usurato, ma visto come è stato trattato, è un miracolo che ci siano ancora tutte le pagine. Proteggilo, $N. Senza di esso non avremo alcuna possibilità di spezzare la maledizione della Torre.', 0),
(10210, 'itIT', '<La luce che ha riempito i tuoi sensi mentre ti avvicinavi ad A''dal s''intensifica quando gli parli. Toni melodici continuano a risuonare nella tua testa.>$B$B<Qui sei al sicuro.>', 0),
(10223, 'itIT', '<Non ne hai la certezza, ma sembra che il Custode Veramorte sia sull''orlo del pianto.>$B$BÈ fatta, finalmente. Se potessi cessare d''esistere solo con la forza di volontà, lo farei. Ma la verità è che non so come dimenticare. Per quelli al villaggio è complicato e semplice allo stesso tempo. Immagino che questo sia il prezzo da pagare per il legame così forte che ho con questo luogo.', 0),
(10227, 'itIT', 'Il bambino ha ragione. Un tempo io ero un "necrosacerdote".$B$B<Ramdor fa una smorfia.>$B$BUn titolo così sgradevole.$B$BIn fondo a quel corridoio si trovano le Cripte degli Auchenai. All''interno troverai ciò che resta della mia prioria. Adesso sono tutti matti, naturalmente. Tutti matti, fino all''ultimo! Evidentemente, essendo rimasto l''unico con un minimo di raziocinio, attiravo l''attenzione e hanno finito con lo scomunicarmi a causa delle mie convinzioni.$B$BQuali sono le mie convinzioni, mi chiedi?', 0),
(10252, 'itIT', 'Straniero... prima non ti ho detto proprio tutto. Dopo aver bevuto questa pozione, vedrai per sempre nel regno dei morti. La pozione che berrai fa parte del rito di iniziazione di tutti i necrosacerdoti di Auchindoun e quando produce i suoi effetti... molti impazziscono. Vedere i morti è... scioccante.$B$B<Nitrin porta la pozione alle tue labbra.>$B$BDesideri procedere comunque?', 0),
(10253, 'itIT', 'Se quel vecchio Draenei ti ha detto di distruggere il libro, perché non l''hai fatto?$B$B<Ramdor ti guarda fisso.>$B$BBah, che differenza fa. Sarai anche avido, ma almeno sei onesto.$B$BIo, invece... per avere questo libro ho mentito. Non ho la minima idea di dove queste povere anime abbiano nascosto i loro tesori, e se l''avessi saputo non te l''avrei mai rivelato! Ma ho comunque qualcosa per te. Oggi hai fatto del bene. Forse una vera impresa... e meriti una ricompensa.$B$BA proposito, benvenuto tra noi.$B$B<Ramdor indica gli spiriti.>', 0),
(10291, 'itIT', 'Abbiamo già perso molti valorosi guerrieri in questa terra maledetta. Non voglio mandare al macello altre reclute inesperte.$B$B<Nazgrel ti squadra da dietro la logora maschera da lupo.>$B$BComunque, se il Generale Krakork ti ha inviato qui, deve aver visto qualcosa in te. Allora, $N, cosa mi dici? Servirai il tuo Capoguerra con onore?', 0),
(10307, 'itIT', '<Il Custode sorride quando nomini Cohlien.>$B$BHai proprio ragione sul cappello. Lo indossava sempre e non lo perdeva mai di vista.$B$BCi sono state un paio di volte in cui un altro Mago, di cui non farò il nome, lo "prese in prestito" e lo nascose per fargli uno scherzo. Inutile dire che la minaccia di uno dei Dardi di Gelo di Cohlien lo fece desistere.$B$BMi mancherà il piccolo Cohlien. Ci sapeva fare con le Elfe.', 0),
(10317, 'itIT', '<Il caposquadra parla sottovoce.>$B$BSei qui per uccidermi? Umpf. Immagino che gli Eterei non sappiano tutto, allora.$B$BNon sono io la persona che cerchi, fidati.', 0),
(10334, 'itIT', '<Prendi il campanaccio dalla sacca, lo suoni un paio di volte e lo mostri a Bessy, che sembra riconoscerlo. La mucca ti permette di metterle il campanaccio al collo e ti guarda speranzosa.>', 0),
(10343, 'itIT', 'Una bomba di mana?$B$B<Morran rigira il frammento.>$B$BÈ quasi inconcepibile! Persino le migliori menti di Dalaran non potrebbero essere riuscite a creare un''arma simile. La mera grandezza del disturbo deve aver aperto uno squarcio dimensionale nel vuoto e ha permesso a queste creature di entrare nelle nostre terre.', 0),
(10351, 'itIT', 'Goliathon? Pathaleon il Calcolatore?$B$BKAEL''THAS!?$B$BIl Principe Kael''thas ha a che fare con questa storia?$B$B<La Plasmaterra perde la calma.>$B$BCiò che ha fatto è pura follia! Far cadere dei cristalli giganti dal cielo e decimare la terra può essere solo opera di un pazzo!$B$BTi assicuro che la Spedizione Cenariana contrasterà qualsiasi altro tentativo di compiere una scelleratezza del genere.$B$B$N, ti siamo enormemente debitori.', 0),
(10355, 'itIT', '<Ruam esamina i campioni con sguardo angosciato.>$B$BProprio quello che temevo, $N. La siccità sta facendo pagare un caro prezzo alle creature adattate a un ambiente paludoso. Dobbiamo continuare a monitorare l''area e consultarci con la Spedizione Cenariana per vedere se si può fare qualcosa.', 0),
(10393, 'itIT', 'Hai fatto bene a portare questa missiva alla mia attenzione. Potrebbe essere l''ordine di produzione di altri Vilrazziatori... o altri piani d''attacco! Avrò bisogno di un po'' di tempo per decifrarla. Lasciami solo: ti farò chiamare quando avrò scoperto qualcosa.$B$B<Il Magistro Falcorosso annuisce quando ti volti per andartene.>$B$B$N, sei una persona sveglia: osserverò con molto interesse i tuoi progressi.', 0),
(10521, 'itIT', '<Grom''tor grugnisce.>$B$BÈ un bene che tu sia qui. Questo verme ha cantato. Sono in nostro potere!', 0),
(10527, 'itIT', '<Il corpo di Ar''tor giace immobile, sospeso a mezz''aria. Non sai da quanto tempo sia morto, ma il tuo cuore piange per Oronok.>$B$B<Forse dovresti provare a tirarlo giù e portare il suo cadavere al padre.>', 0),
(10528, 'itIT', '<Inserisci la Chiave Cristallina negli incavi alla base di ogni Cristallo Demoniaco.>', 0),
(10540, 'itIT', '<Ar''tor appare e scompare.>$B$BSembra che si avvicini il mio momento.', 0),
(10541, 'itIT', '<Oronok si asciuga la lacrima e ti sorride.>$B$BGrazie. Ti prometto che sarà scritta una ballata in tuo onore.', 0),
(10546, 'itIT', '<Borak per un momento rimane in silenzio.>$B$BSono settimane che osservo gli Elfi del Sangue, cercando di capire dove nascondono la terza parte del Cifrario della Dannazione.$B$BFinora, non ho scoperto nulla. L''unica cosa che so è che Illidan, una volta al giorno, manda qui un inviato dal Tempio Nero.$B$BÈ intoccabile. L''ho pedinato per giorni, cercando di capire come separarlo dalla sua guardia. Sfortunatamente, non lo lascia mai.', 0),
(10547, 'itIT', 'Hai un Uovo di Arakkoa Marcio? Perché non l''hai detto subito! Credo che potremo fare affari.$B$B<Tobias sorride, mostrando denti lerci e putrescenti.>', 0),
(10563, 'itIT', '<Il Comandante di Squadriglia Nuainn ascolta il tuo rapporto, allarmandosi sempre di più a ogni frase.>$B$BMi stai dicendo che hanno abbastanza Infernali per intensificare il bombardamento? Se non li fermiamo prima che possano passare alla prossima fase del loro piano, la Roccaforte dei Granmartello è condannata.', 0),
(10578, 'itIT', 'Finalmente! Il frammento del Cifrario è nostro!$B$B<Borak colloca il frammento in una cassetta.>', 0),
(10642, 'itIT', '<Zorus inizia a creare qualcosa con i campioni di cenere.>$B$BHo finito. Ammira le Lenti Spiritate!', 0),
(10643, 'itIT', 'Sostieni che gli spiriti ti sussurravano qualcosa? E hanno parlato di Teron Malacarne?$B$B<Zorus ha un brivido.>$B$BSì... conosco Teron Malacarne. O meglio, lo conoscevo. Si pensava che fosse morto ormai da tempo. Di cosa staranno parlando gli spiriti?', 0),
(10657, 'itIT', 'Accidenti, ha funzionato! A voler essere onesti, non ne ero sicuro... Avevo calcolato una probabilità del 23,72 percento che saresti imploso entro la terza scarica.$B$B<Toshley sorride innocentemente.>$B$BBene, ora che sappiamo che il Magnete funziona, non avremo problemi ad alimentare lo Zephyrium Capacitorium... se troviamo altri volontari disposti a farsi fulminare, ovviamente.$B$BIn ogni caso, grazie a te abbiamo compiuto un passo avanti e meriti qualcosa in cambio!', 0),
(10661, 'itIT', '<Gnomus afferra avidamente le milze.>$B$BEcco il denaro che ti avevo promesso. Ti chiamerò se me ne servono altre.$B$BDeliziose... Oserei dire che sono "milziche"!', 0),
(10664, 'itIT', '<Il fabbro prende i materiali, annuendo soddisfatto.>$B$BAndranno bene. Gli altri materiali che mi servono non saranno così facili da trovare.', 0),
(10666, 'itIT', '<David sfoglia le pagine del libro e rabbrividisce.>$B$BNon bisogna scherzare con questo libro, $N. Dopo che avrò creato l''arma, lo distruggerò. C''è abbastanza potere demoniaco nel mondo anche senza questo libro.', 0),
(10676, 'itIT', '<David si asciuga il sudore dalla fronte.>$B$BIl grosso del lavoro è fatto, ma per applicare gli incantesimi devo prima temprare la lama.', 0),
(10679, 'itIT', 'Ben fatto!$B$B<Il fabbro esamina attentamente la lama.>$B$BDirei che è migliorata molto rispetto alle rozze armi della Legione con cui hai iniziato. Non solo questa lama abbatterà i Demoni Illidari, ma funzionerà anche contro i servitori della Legione.', 0),
(10705, 'itIT', '<Il Veggente Linguamorta è deceduto da tempo. Girando il cadavere, scopri delle scritte sul terreno.>', 0),
(10759, 'itIT', '<L''Arakkoa ridacchia.>$B$BSì, sono il disertore di cui parla il diario del comandante. Attendevo il giorno in cui gli altri si fossero accorti della minaccia rappresentata da coloro che un tempo chiamavo fratelli.', 0),
(10761, 'itIT', '<L''Arakkoa ridacchia.>$B$BSì, sono il disertore di cui parla il diario del comandante. Attendevo il giorno in cui gli altri si fossero accorti della minaccia rappresentata da coloro che un tempo chiamavo fratelli.', 0),
(10777, 'itIT', '<Parshah esamina il totem.>$B$BBene. Questo vecchio totem non ha perso il suo potere nonostante gli anni, ma non è sufficiente a fermare il Conclave Oscuro.', 0),
(10780, 'itIT', '<Parshah prende le piume sporche di cenere, scuotendo la testa.>$B$BSarebbe stato meglio se fossero morti quel giorno, ma nulla è mai così semplice. La magia di Gul''dan li ha trasformati in ciò che stavano cercando di fermare. Che crudele scherzo del destino.', 0),
(10782, 'itIT', '<Parshah prende il pomolo con cautela.>$B$BContiene il potere che ci servirà per fermare il Conclave Oscuro al Campo Base di Sketh''lon.', 0),
(10796, 'itIT', '<Il tenente annuisce, chiaramente soddisfatta della tua abilità guerriera.>$B$B$N, sono impressionata. La tua reputazione è ben meritata.$B$BOgni Ogre abbattuto rappresenta un passo in avanti nell''estirpazione di una minaccia che non sembra avere la minima intenzione di lasciarci in pace.', 0),
(10800, 'itIT', '<Il Barone Nerocrine scruta all''interno della sacca del Gronn e sembra soddisfatto.>$B$BMolto bene. Hai ottemperato alla tua parte dell''accordo. Ora posso donare al tuo Comandante Pietramuro la trappola che chiedeva.', 0),
(10913, 'itIT', '<Il Comandante Ra''vaj si regge la testa tra le mani.>$B$BNon basta... non basta.', 0),
(10917, 'itIT', '<Vekax gracchia di gioia quando gli porti la prova della morte dei suoi nemici.>$B$BSì, in questo modo Skettis capirà che noi Erranti non subiremo senza reagire. Ecco la ricompensa che ti avevo promesso... Se mi porti altre piume, posso darti di più.', 0),
(10943, 'itIT', 'Devi essere l''avventuriero che sarà il mio fratellone per la Settimana dei Bambini! Sono Dornaa, piacere.$B$B<Per un attimo, ti sembra triste.>$B$BMamma e papà sono stati uccisi nella guerra e ho vissuto per tutta la vita nell''orfanotrofio. È bello, ma ho sempre desiderato esplorare il mondo.$B$BHo già fatto un elenco dei posti che vorrei visitare, se per te va bene. Sono sicura che ci divertiremo un sacco insieme!$B$BSono pronta a partire quando vuoi!', 0),
(10956, 'itIT', '<Più che udire, senti risuonare nella tua mente la voce musicale di O''ros.>$B$BGrazie per avermi portato questa bambina, $N. È speciale e un giorno sarà una personalità importante tra i Draenei, anche grazie alla gentilezza che le hai dimostrato e all''impressione che le hai fatto.', 0),
(10962, 'itIT', 'Fantastico! Un drago tutto per me! Spero un giorno di poter avere un drago per amico.$B$B<Dornaa saltella in preda alla felicità, impugnando il suo Drago Giocattolo.>$B$BÈ stato il viaggio più bello della mia vita! Spero non finisca mai!', 0),
(10963, 'itIT', 'Meraviglioso! Un drago tutto per me! Un giorno ne avrò uno vero.$B$B<Salandria guarda sorniona il suo nuovo giocattolo, capisci che sta pensando qualcosa.>$B$BÈ stato il viaggio più bello della mia vita! Spero non finisca mai!', 0),
(11007, 'itIT', '<I pensieri di A''dal''s si fondono con i tuoi.>$B$BLa sfera... Strano. Sapevi che è sopravvissuto? Sì. È qui, proprio nella sfera. Di sicuro è ferito. Ora si rivolge a un potere superiore. No, non Illidan.$B$BSuperiore.$B$BKil''jaeden l''Ingannatore arriva...$B$BNon qui...$B$B<A''dal dirige altrove la tua mente.>$B$BAzeroth. Sconosciuto.$B$BRiposa. I tuoi fratelli e le tue sorelle riprenderanno Forte Tempesta.$B$B<A''dal bisbiglia una canzone di battaglia.>', 0),
(11020, 'itIT', '<Yarzill bisbiglia.>$B$BEccellente lavoro, $N. Per ora, tieni un profilo basso. Torna da me domani e potremo rifarlo.', 0),
(11035, 'itIT', '<Yarzill bisbiglia.>$B$BStai rendendo un grande servigio agli Alafatua, $N. Lentamente, rovesceremo le Fauci di Drago. Al loro interno si sta diffondendo un morbo, un morbo senza cura...$B$BTorna da me domani se vuoi operare ancora allo Stretto delle Fauci di Drago.', 0),
(11043, 'itIT', '<Il volto di Brunn s''infiamma fino a diventare rosso come la sua barba.>$B$BCOSA vuole fare ai MIEI grifoni?$B$BSe quella mezza cartuccia osa mettergli addosso qualcos''altro oltre alla sella, andrò personalmente a Spinaguzza a legargli quel suo razzo alla gola!', 0),
(11066, 'itIT', 'Continui a sorprendermi! Ti dirò... perché non torni domani? Forse tu non hai bisogno di riposare, ma la corda sì!$B$B<Khatie ride.>$B$BGrazie mille, $N!', 0),
(11089, 'itIT', '<Balthas assembla con abilità i componenti che gli hai portato.>$B$BOra possiamo procedere alla seconda parte del piano, Capitano.', 0),
(11101, 'itIT', '<Mor''ghor ride.>$B$BAh ah ah! Sapevo che non mi avresti deluso, Comandante! Voglio che tu conduca un''incursione all''Altare degli Sha''tar almeno una volta al giorno. Non avranno alternative se non abbandonare Torvaluna!', 0),
(11108, 'itIT', 'Sai, sono stato il primo. Il figlio abbandonato di un mostro...$B$B<Barthamus scuote la testa.>$B$BTi dobbiamo tutto, $N. Hai sbriciolato da solo l''impero delle Fauci di Drago e raccolto abbastanza informazioni da tenere occupati i miei fratelli per dieci vite.$B$BNon è molto, ma c''è qualcosa che possiamo offrirti... I miei fratelli si sono tutti offerti per seguirti nella tua missione nelle Terre Esterne. Chiedi e si legheranno a te.', 0),
(11187, 'itIT', '<Malister ti fa cenno di avvicinarti e parla sottovoce.>$B$BTemevo che una cosa del genere potesse accadere. Ho tentato di dissuadere il Capitano, ma è un Nano d''azione e ha sempre un''idea molto precisa su come procedere.$B$BParliamo delle opzioni che ci rimangono.', 0),
(11188, 'itIT', '<Il Vice Mago sospira.>$B$BÈ stata un''azione davvero incresciosa. Be'', è inutile piangere sul latte versato. Con un po'' di fortuna, i draghetti che cresceranno a Selvardente non ricorderanno la nostra vergognosa condotta.$B$BE con un pizzico di fortuna in più, i confini della foresta magica smetteranno di espandersi.$B$B$N, ecco il tuo compenso: è il minimo che possiamo fare per sdebitarci.', 0),
(11208, 'itIT', '<Drazzit prende il carico da te.>$B$BHo talmente tanta fame che potrei mangiare un drago! Grazie al cielo Moxie è riuscita a inviarci parte del carico. Ci siamo ridotti a giocare a dadi con un Ogre per ottenere il bottino delle sue battute di caccia!', 0),
(11218, 'itIT', 'Il minerale ti ha fatto provare una strana sensazione? Forse non è il caso di usare quella roba.$B$B<Duranello guarda il minerale e fa un passo indietro, cambiando argomento.>$B$BLe gemme sono bellissime! Chissà quanto riuscirò a ricavarne? Ovviamente, ci sono sempre le riparazioni e nuovi oggetti da creare.$B$BLavorare con te è davvero proficuo, sai? Tieni... è il minimo che possa fare!', 0),
(11239, 'itIT', '<Il Sacerdote mormora sottovoce una benedizione diretta a te.>$B$B$N, che tu sia benedetta per aver risposto alle mie preghiere. Cammina a testa alta nella Luce, con la consapevolezza che le tue azioni sono sante!$B$BSono sicuro che nelle casse della chiesa c''è qualcosa che può tornarti utile.', 0),
(11240, 'itIT', '<Il Geniere borbotta, come se si fosse augurato che fallissi.>$B$BIl Capitano sarà felice di apprendere del tuo successo.$B$BVisto che te la sei cavata così bene nella Gola dei Sussurri, perché non scegli la tua ricompensa?', 0),
(11253, 'itIT', '<Questa pergamena scagliosa è ricoperta di figure stilizzate. Hai il sospetto che fosse questo il tipo di indizi che il Guardiano del Canile ti ha chiesto di cercare.>', 0),
(11254, 'itIT', '<Il Gran Esecutore esamina a fondo la mappa, concentrandosi di tanto in tanto sui simboli sparsi per il Fiordo.>$B$BQuesta è la costa orientale. I villaggi degli Scorticadraghi e dei Geloskorn sono qui e qui... e questi dobbiamo essere noi, con il simbolo della morte sopra.', 0),
(11257, 'itIT', 'Non è la prima volta, vero? Mi sembri piuttosto abile con il mio machete.$B$B<Il Guerriero ti guarda con sospetto e timore.>$B$B$c, d''ora in poi questo lo tengo io.', 0),
(11258, 'itIT', '<Il guerriero annuisce, approvando il modo in cui usi la torcia.>$B$BFacciamo sentire a quei Vrykul come brucia questa terra! Che il loro terrore si propaghi anche agli altri!', 0),
(11264, 'itIT', '<Il Capo Tribù Totem Sabbioso tira un sospiro di sollievo.>$B$BQuesto dovrebbe farci dormire sonni più tranquilli.$B$B$N, ancora una volta ti sei dimostrato un aiuto preziosissimo per i Taunka dell''Accampamento degli Zoccolo Artico. Insisto che tu scelga una ricompensa.', 0),
(11268, 'itIT', '<La Granmadre annuisce, approvando le tue gesta.>$B$BGrazie, $N! Hai fatto ciò che è giusto e ci hai fatto guadagnare un po'' di tempo per i preparativi della partenza. Presto intraprenderemo il viaggio verso nord.$B$BSono vecchia e, quando partiremo, non potrò portare tutto con me. Perché non prendi uno dei miei oggetti?', 0),
(11273, 'itIT', '<Hai trovato Pulroy. Troppo tardi, a quanto pare.>$B$B<Esaminando la salma, scopri che stringe in mano un diario. A una rapida occhiata, sembra pieno di scarabocchi del Nano morente.>', 0),
(11274, 'itIT', '<Hai trovato Zedd. Non sei un medico, ma la sua prognosi è sicuramente negativa.>$B$B<Sembra volessero darlo in pasto ai Worg. Che orrore...>', 0),
(11276, 'itIT', 'Era ora, dannazione! Pulroy e Zedd sono morti.$B$BPer quanto riguarda Daegarn...$B$B<Glorenfeld scuote la testa.>$B$BÈ stato trascinato in fondo alle Catacombe dal Capo Tribù degli Scorticadraghi. Ho sentito quel cane troppo cresciuto parlare di un certo sacrificio al "Re del Terrore".$B$BIl Cifrario è nascosto nella barba sudicia di Daegarn.$B$BChe c''è? I Nani nascondono sempre gli oggetti nelle loro barbe!', 0),
(11280, 'itIT', 'NOOOOOOOOOOOOOOOO!!!$B$B<L''Araldo della Piaga scoppia in lacrime.>$B$BTutte le mie speranze... tutti i miei sogni... distrutti!$B$B$N, lasciami solo con il mio dolore. Sono una nullità.$B$BEcco, prendi tutti i miei beni materiali: quando gli altri Speziali sapranno del mio fallimento, sarò finito e non mi serviranno più.', 0),
(11281, 'itIT', '<Nokoma ascolta i risultati della prova.>$B$BÈ un sollievo apprendere che il corno ha funzionato bene... persino troppo, se quel che dici è vero. Sei sicuro che la bestia abbia parlato? In questo caso, non so se riuscirei a proseguire con la caccia. Devo parlarne con il Capo Tribù Totem Sabbioso.$B$BQuesto corno potrebbe diventare un oggetto puramente decorativo, ma ciò non ne sminuirebbe il valore. $N, grazie per il tuo aiuto.', 0),
(11286, 'itIT', '<Il Saggio emette un ringhio d''approvazione per le tue azioni.>$B$BForse presto riuscirò a trovare il tempo per studiare questi manufatti e scoprirne il significato.$B$BOra, però, abbiamo faccende più urgenti da sbrigare.', 0),
(11288, 'itIT', '<Qualcosa ti spinge a posare la Lama Sacra vicino al corpo di Ares.>$B$B<Subito dopo, vieni nuovamente accecato dalla luce.>', 0),
(11290, 'itIT', '<Il Viceammiraglio Keller da'' un''occhiata veloce ai piani.>$B$BIncredibile! Secondo questi piani, ci sono molti altri villaggi di Vrykul nel Fiordo. Un''altra tribù si sta preparando ad assaltare il Forte di Guardia dell''Ovest. Per quanto ne sappiamo, potrebbe già essere troppo tardi: sono giorni che non abbiamo notizie dal Forte! In ogni caso, bisogna avvisare la Guardia dell''Ovest!', 0),
(11291, 'itIT', '<Il Capitano Adams prende i piani dalle tue mani.>$B$BSono felice che tu sia qui. Io e i miei consiglieri abbiamo bisogno di tempo per studiare i piani. Nel frattempo, il tuo aiuto ci farebbe veramente comodo!', 0),
(11292, 'itIT', '<Il Mastro Bracconiere Jethan esamina le creature che gli hai portato.>$B$BBen fatto. Alcune valgono di più, altre di meno... ma non dovrei avere problemi a commerciare con gli abitanti locali.', 0),
(11298, 'itIT', '<Lo speziale versa un boccale della bevanda per sé.>$B$BBe'', alla salute!', 0),
(11299, 'itIT', 'Sì, mi hai trovato. Evviva!$B$BE no: non ho il Cifrario. Come prima cosa, quelle bestie sono andate a cercare nella mia barba! Adesso ce l''ha Oluf, il comandante dei gladiatori.', 0),
(11302, 'itIT', '<Lurielle ascolta la tua presentazione.>$B$B$N, sono felice di incontrarti. Da lungo tempo speravamo che tu e gli altri nuovi arrivati inviaste qualcuno a contattarci. Non ci avventuriamo spesso oltre i confini della nostra Radura, soprattutto ora che la regione è scossa da tali cambiamenti.', 0),
(11312, 'itIT', '<Lurielle ti ascolta mentre ti presenti.>$B$BFelice di conoscerti, $c. Spesso le mie sorelle hanno osservato i Taunka che ci cercavano nelle foreste, ma la nostra Regina ci ha proibito di interagire con gli stranieri. Puoi vederci solo perché la regione è sconvolta e molte delle mie sorelle sono in pericolo.', 0),
(11314, 'itIT', 'Quindi c''è speranza per le mie sorelle?$B$B<Lurielle distoglie lo sguardo da te, posandolo a terra.>$B$BMi sento in colpa per non aver pensato prima al Pendente. Avremmo potuto salvarne di più.', 0),
(11330, 'itIT', 'Eh? Che peccato! Accidenti, ho peggiorato la shituazione. In effetti, credo di averli aiutati a perfezionare la piaga...hic!$B$B<Peppy fa una smorfia e tracanna un gran sorso della birra malsana che sta bevendo.>$B$BBe'', shperavo di non dover arrivare a queshto punto, ma shembra proprio che non ci shia alternativa... hic.', 0),
(11333, 'itIT', 'È un po'' malandata, ma servirà al suo scopo.$B$B<Thoralius fruga nella borsa e ne estrae alcune strane radici.>$B$BOra devo solo gettarle nel fuoco e inalarne i vapori!$B$B<Thoralius getta le radici nell''Incensiere rovente.>$B$B<Dopo aver inalato a fondo, il suo corpo inizia a tremare.>$B$BChe... cosa... Non può essere... Non posso...', 0),
(11344, 'itIT', 'Bambini umani nati da Vrykul? Ymiron ha ordinato la morte di tutti i bambini nati Umani?$B$B<Thoralius ammutolisce per un istante.>$B$BVorrei tanto negare l''evidenza, ma non posso: non c''è nessun "anello mancante" con la stirpe degli Umani, come crede la Lega degli Esploratori. Sono i Vrykul, l''anello mancante! Sono loro i progenitori dell''umanità!', 0),
(11346, 'itIT', '<Il Prospettore Belvar scorre il Libro delle Rune.>$B$BMmm... c''è così tanto da leggere! Avrò bisogno di un po'' di tempo per studiarlo. Se vogliamo capire queste rune, dobbiamo tentare di riprodurle.', 0),
(11349, 'itIT', '<Belvar maneggia con cautela gli strumenti.>$B$BLi provo subito. Se vogliamo scoprire i piani dei Nani del Ferro e sventarli, devo sapere esattamente come funzionano le rune.', 0),
(11350, 'itIT', '<Lo Staffettista scorre il Libro delle Rune.>$B$BNon sono uno storico, ma ho una certa familiarità con la lingua dei Nani del Ferro. Credo che le rune incise sui giganti derivino dalla lingua parlata dei Nani, ma ci sono alcune differenze.', 0),
(11351, 'itIT', '<Pembe esamina gli strumenti.>$B$BSono più delicati di quanto pensassi. Dammi un momento per provarli.', 0),
(11355, 'itIT', '<Il Ricercatore Aderan ascolta il racconto delle tue scoperte.>$B$BLe rune che indicavano "nord" e "ovest" sono apparse più volte? È un ordine perentorio a muoversi in quella direzione, ma le rune non sono un semplice mezzo di propulsione. Qualcosa attrae i giganti... ma cosa?', 0),
(11358, 'itIT', '<Aderan ascolta il racconto delle tue scoperte.>$B$BMa certo! Megalith dev''essere la chiave dei piani dei Nani del Ferro. Dobbiamo distruggerlo prima che riescano nella loro impresa!', 0),
(11365, 'itIT', '<Il Saggio ascolta il racconto delle tue scoperte.>$B$BLe rune che indicavano "nord" e "ovest" sono apparse più volte? Non sono un esperto, ma la ripetizione sembrerebbe indicare un ordine perentorio.$B$BLe incisioni non sono delle semplici indicazioni. Sembrano spingere i giganti verso qualcosa... ma cosa?', 0),
(11366, 'itIT', '<Edan ascolta il racconto delle tue scoperte.>$B$BMegalith? Una trascrizione letterale dalla tavoletta! Deve essere la chiave dei piani misteriosi dei Nani del Ferro.', 0),
(11379, 'itIT', 'Guarda, guarda...$B$B<Rokk assaggia la pietanza e il suo volto si contorce in una bizzarra smorfia di dolore e delizia.>$B$BPer A''dal, che bontà! Una cuoca col tuo potenziale dovrebbe avere delle scorte tutte sue. Prendine un po'' delle mie e rendimi orgoglioso.', 0),
(11393, 'itIT', '<Appena sente chi è stata a mandarti, il volto dell''esploratore si illumina ed egli continua a parlare sottovoce.>$B$BIrena era preoccupata per me? Ha proprio preso da suo padre.', 0),
(11394, 'itIT', '<Jaren è molto emozionato per il tuo successo, ma ti fa cenno di continuare a parlare sottovoce.>$B$BOttimo lavoro, $N! Però sei pieno di lordura del Flagello. Fa'' un breve bagno nello stretto. È freddo, ma ti ripulirà in un baleno.', 0),
(11397, 'itIT', '<Anastasia medita un istante sul tuo successo.>$B$BHai fatto senza dubbio un ottimo lavoro, anche se sento che potremmo fare ancora qualcosa per sventare i piani del Flagello su quella spiaggia.', 0),
(11399, 'itIT', '<Anastasia si volta e sorride.>$B$BMolto bene, $N: hai diritto a scegliere la tua ricompensa fra queste.', 0),
(11406, 'itIT', 'Ti ha inviato il Quartiermastro?$B$B<Gil sembra sollevato.>$B$BA dire il vero, siamo un po'' in ritardo e abbiamo bisogno d''aiuto per farcela in tempo.$B$B<Gil scrolla le spalle.>$B$BNessuno vuole sfidare le ire del Capitano Adams.', 0),
(11416, 'itIT', '<Ulfang ulula sonoramente per celebrare la tua vittoria sulla sua grande nemica.>$B$BL''onore dell''uccisione è tuo. Avrei voluto essere io a stringere il suo collo fra le mie fauci.$B$BNon sprechiamo il suo sacrificio. Presto, mangiali!', 0),
(11417, 'itIT', '<Ulfang ulula sonoramente per celebrare la tua vittoria sulla sua grande nemica.>$B$BL''onore dell''uccisione è tuo. Avrei voluto essere io a stringere il suo collo fra le mie fauci.$B$BNon sprechiamo il suo sacrificio. Presto, mangiali!', 0),
(11418, 'itIT', 'Hai visto un nido con dei pulcini? Mmm... Quindi "lui" in realtà è una "lei", eh?$B$BQuesto spiega tutto. Nemmeno io vorrei spostare un nido pieno di pulcini, solo perché ho dei nuovi vicini.$B$B<Gil lancia un''occhiata divertita al Mastro Bracconiere.>$B$BSono sicuro che andremo molto d''accordo, sempre che il nostro Jethan la pianti di volerla trasformare in un trofeo di caccia.', 0),
(11420, 'itIT', '<Zorek scorre rapidamente il manuale.>$B$BInteressante...$B$BSecondo il manuale, i Vrykul possiedono uno strumento speciale, che permette di controllare i Lancia Arpioni con estrema precisione. Assomiglia un po'' al timone di una delle nostre navi. Inoltre, è trasportabile e si infila nei Lancia Arpioni come una chiave. Devi procuracene uno!', 0),
(11422, 'itIT', '<Al Vecchio Pinnagelo trema un po'' la mano, mentre la allunga verso di te per prendere il tridente di suo figlio. Possibile che il vecchio Murloc stia soffrendo?>$B$B<Quello nel suo occhio è solo un accumulo di umidità in eccesso?>', 0),
(11427, 'itIT', '<Il Tenente Acremartello prende il Controllo del Lancia Arpioni dalle tue mani.>$B$BAh, mi hai portato un regalo!', 0),
(11448, 'itIT', '<Stanwad prende il pacchetto e inizia a leggere le tavolette.>$B$BQuanta gente hai detto che è morta per recuperare queste informazioni?$B$B<Stanwad scuote la testa.>$B$BSarai felice di sapere che McSorf e la sua squadra di imbecilli hanno scoperto un''antica ricetta per lo Stufato della Tundra. Non ha visto le icone raffiguranti le verdure? O il disegno di un umanoide che le mangia? Non ho bisogno di un maledetto Cifrario per decodificare questa roba!', 0),
(11504, 'itIT', '<I baffi di Orfus vibrano.>$B$BPirati... Possibile che la loro depravazione non abbia limiti?$B$BDobbiamo recuperare i manufatti rubati e riportarli nel posto maledetto cui appartiengono. Solo così il mio popolo potrà ritrovare la pace.', 0),
(11509, 'itIT', '<Harry solleva un sopracciglio.>$B$BE così sei come me, eh? Un po''... eccentrico.$B$B<Harry sospira.>$B$BDa queste parti, nessuno si veste in questo modo.$B$BRiguardo ai manufatti di cui mi hai chiesto... Chiunque sia entrato in contatto con quegli oggetti è morto, sparito o entrambe le cose.$B$BSe insisti a volerne sapere di più, posso aiutarti... ma ti costerà.$B$B<Harry ammicca.>$B$BTu fai un favore a me e io... ti faccio il favore di non accoltellarti alla schiena.', 0),
(11510, 'itIT', '<Harry prende il cristallo dalle tue mani e lo coccola delicatamente.>$B$BAh, il mio tesoro! Quella brutta orca cattiva ti ha fatto del male? Andrà tutto bene, vedrai: non ti perderò più di vista!$B$B<Harry solleva lo sguardo su di te.>$B$BAllora, di cosa stavamo parlando?', 0),
(11519, 'itIT', 'Arrr! Quello stramaledetto Scudo l''abbiamo rubato io e la mia ciurma! Stiamo cercando di riprendercelo da quel furfante d''acqua dolce buono a nulla di Sorlof! Sei qui per dare una mano, arrr?$B$BBe'', come vedi la ciurma è composta tutta da scheletri!$B$B<Il Capitano Ellis ride.>$B$BAlla Sorella Pietà serve qualcuno che trasporti la Polvere Esplosiva al Bombardone del cassero di prua. Credi di potercela fare, filibustiere?$B$BAiuta la mia ciurma a eliminare Sorlof e ci divideremo il tesoro! Tu potrai tenerti lo Scudo... e noi tutto il resto!', 0),
(11565, 'itIT', '<Al vedere il travestimento da Murloc di ricambio, il Re si strofina le false appendici.>$B$BOttimo. E ora torniamo a questioni più urgenti. Ho un incarico di grande importanza da affidarti.', 0),
(11585, 'itIT', 'Un eroe dell''Orda, eh?$B$B<Garrosh odora l''aria intorno a te.>$B$BPaura...$B$B<Garrosh sputa.>$B$BNon durerai a lungo.', 0),
(11599, 'itIT', '<Il cadavere corrisponde alla descrizione di William Allerton che ti ha dato Leryssa. Stranamente, non presenta segni di morsi o graffi.>', 0),
(11605, 'itIT', '<Mentre ti avvicini alla sua statua, la voce dell''Anziano Atkanok ti saluta.>$B$BBen fatto, $N. Ora che conosco i nomi degli spiriti erranti, possiamo proseguire la cerimonia interrotta dall''attacco nemico. Tuttavia, prima di ricondurre gli spiriti degli anziani alle loro statue, dobbiamo quietare gli spiriti degli artigiani e degli Sciamani uccisi, altrimenti gli spiriti degli anziani non potranno udire il richiamo del cerimoniale.', 0),
(11609, 'itIT', '<Mostri gli oggetti rituali alla statua dell''Anziano Atkanok.>$B$BAnche se non sono in ottime condizioni, andranno bene. Alcuni sono sopravvissuti a secoli di utilizzo solo per essere danneggiati e rubati da barbari!', 0),
(11614, 'itIT', '<Più morto di così, si muore... Stranamente, i Nerubiani non hanno divorato il cadavere.>$B$B<Dopo aver esaminato il corpo attentamente, capisci che Luther si è ucciso da solo con del veleno. Furbo. I Nerubiani non toccherebbero neanche con un dito della carne così tossica.>$B$B<Noti che Luther ha in mano un diario.>', 0),
(11615, 'itIT', '<Barthus passa direttamente all''ultima pagina e comincia a leggere.>$B$BQuesta è una pessima notizia. Bisogna avvertire subito Malogrido.', 0),
(11616, 'itIT', '<Malogrido legge la pagina di diario.>$B$BÈ tutto?', 0),
(11628, 'itIT', 'Per quanto preferirei tenere queste pelli contaminate fuori dal villaggio, alla fine potrebbero rivelarsi utili contro i nostri nemici.$B$B<Il Capo Tribù fa segno alla Saggia Aeire di portar via le pelli.>$B$BMentre lei preparerà le pelli, tu dovrai procurarti un altro elemento necessario per creare il mantello.', 0),
(11630, 'itIT', '<Il Capo Tribù Bora Fredda raccoglie con circospezione le zolle di terra da te recuperate.>$B$BDobbiamo darle alla Saggia Aeire il prima possibile.$B$B<Il Capo Tribù grugnisce, fingendo di non essere turbato dalla terra contaminata.>$B$BIl comandante del Flagello potrebbe lanciare l''assalto finale al villaggio da un momento all''altro.', 0),
(11634, 'itIT', 'Ué, cumpà. Ti stavo aspettando.$B$B<To''bor indica a ovest.>$B$BDai no sguardo. Oltre chella Tundra ci sta la morte, cumpà... la morte.', 0),
(11640, 'itIT', '<Il Capo Tribù Bora Fredda legge le parole scritte sulle pergamene.>$B$B"Shabtir bakh sokhen".$B$BParole dell''antica e aspra lingua dei Nerubiani, molto indicative...$B$B"Il servitore s''inchina all''autorità del padrone". Con queste parole potrai accedere alla necropoli.', 0),
(11647, 'itIT', '<La Saggia Aeire riceve il totem dalle tue mani.>$B$BHa funzionato? Per prepararlo ho dovuto fare ricorso ad antiche magie che i Saggi non usano da generazioni. Di tutte le conoscenze tramandate, oggi se ne utilizza solo una minima parte.', 0),
(11653, 'itIT', 'Come sarebbe a dire, non funziona?!?$B$BMa... ma...$B$B<Crafty comincia a singhiozzare.>$B$BVa bene, posso farcela. Non sono più una ragazzina. Devo solo pensare creativamente!', 0),
(11654, 'itIT', '<Il Braccatore delle Nevi Taunka sembra debole e riesce a malapena a risponderti.>$B$BNon mi resta ormai... molto. Forse... forse puoi fermarli... prima che...', 0),
(11655, 'itIT', '<Waltor è sopraffatto dalla tristezza.>$B$BRovine... questo è ciò che resta dopo il loro passaggio. Bisogna dargli una lezione.', 0),
(11661, 'itIT', 'A quanto pare, l''uccisione del Tenente ha solo agitato di più le acque: sono ancora più feroci e aggressivi di prima!$B$B<Waltor sospira.>$B$BAmico mio, qui hai fatto tutto ciò che potevi. Se non altro, meriti una ricompensa per aver ridotto il loro numero.', 0),
(11677, 'itIT', '<La Saggia tira un grosso sospiro di sollievo.>$B$BUn ottimo inizio. Se solo questo fosse l''unico problema...', 0),
(11684, 'itIT', '<Il Padre Anziano Mahan prende la mappa dalle tue mani, ma non accenna a consultarla.>$B$BUtilizzeremo le informazioni da te raccolte più tardi, quando saremo pronti per mettere in pratica un piano.', 0),
(11686, 'itIT', 'È peggio di quanto annotato sul Diario di Luther. Il Flagello ha il controllo assoluto di questo posto e sta infettando tutto ciò che tocca.$B$B<Ickoris annuisce tra sé.>$B$BE al peggio non c''è mai fine...', 0),
(11689, 'itIT', 'Che notizie mi porti da Alta Mesa?$B$B<Spieghi ciò che sai e dai alla Madre Anziana la cattiva notizia della morte dello Staffettista Corno Peloso.>$B$BIl mio... il mio nipotino!$B$B<La Madre Anziana lotta per controllare le proprie emozioni.>$B$BÈ morto con onore, come un vero Taunka!$B$BTu sei stato l''ultimo a vederlo, $N, per cui farà sempre parte di te. Ti ringrazio per aver esaudito i suoi ultimi desideri.', 0),
(11695, 'itIT', '<Barah riceve i pezzi del corno dalle tue mani e si mette subito all''opera per ricomporli.>$B$BZoccolo Tempestoso sarebbe orgoglioso di te, $N. Quando avremo sconfitto il Flagello, ho intenzione di andare in pellegrinaggio alla sua tomba portando con me il corno.', 0),
(11703, 'itIT', '<Getry ti squadra.>$B$BE tu saresti il meglio che ha potuto mandarmi Ickoris?', 0),
(11705, 'itIT', 'Ed eccoti vittorioso, proprio come pensavo! L''avevo detto, a Faucisaure, che su di te si poteva contare.$B$B<Malogrido grugnisce soddisfatto.>$B$BQuesto forse servirà a dimostrare a quel vecchio sciocco che non ha tutte le risposte!', 0),
(11709, 'itIT', '<Nork sogghigna.>$B$BPrigionieri? Questi non sono prigionieri, sono dei cani codardi! Guardali. Lo sapevi che ciascuno di questi "soldati" dal ventre giallo, senza eccezione alcuna, è giunto ai nostri cancelli consegnandoci le sue armi e armature?$B$BA quanto ho capito, chi viene fatto prigioniero da noi una volta liberato può tornare a casa, senza dover più combattere.$B$B<Nork sputa.>$B$BPatetico...', 0),
(11713, 'itIT', '<Abner riceve la mappa da te e la esamina con cura.>$B$BOttimo! Queste erano le informazioni che ci servivano per dare il via all''operazione.', 0),
(11715, 'itIT', '<Abner inizia a svuotare il serbatoio del Raccoglitore.>$B$BDistillarlo a mano sarà un bel problema, ma me ne occuperò presto. Nel frattempo, per completare la macchina ci serve dell''altro materiale.', 0),
(11716, 'itIT', 'Perfetto! Assolutamente perfetto!$B$B<Laurith spruzza un po'' di polline su un campione di Fogliame Interno di Sporasangue e poi mormora un incantamento.>$B$BUmpf... non capisco. A meno che... ma certo!', 0),
(11717, 'itIT', 'A-ha!$B$B<Laurith spruzza il Polline di Falena sui campioni di Fogliame Interno di Sporasangue.>$B$BGuarda!', 0),
(11718, 'itIT', '<Abner ispeziona le pelli, tossendo per tutta la polvere sollevata.>$B$BMa quelle bestie non ci provano neanche, a pulirsi? Alcune sono totalmente luride. Be'', forse è meglio cominciare a lavarle. Non abbiamo tempo da perdere.', 0),
(11722, 'itIT', '<Malogrido prende la Testa di Gammothra e le sputa addosso.>$B$BImpareranno, $N... impareranno tutti. Scherzare con l''Orda non è una buona idea.', 0),
(11723, 'itIT', '<Abner ascolta felice il rapporto del tuo successo e del successo del Tremazinga 5000.>$B$BFrizzapistone sarà contento di saperlo! E chissà... magari faremo di te un meccanico provetto!', 0),
(11725, 'itIT', 'Grazie al cielo... è stato terribile.$B$BHo visto un lampo luminoso a terra e poi, all''improvviso, l''intero squadrone stava precipitando! Sono gravemente ferito, per cui non ho potuto setacciare l''area in cerca di altri superstiti, ma qualcosa mi dice che non sono molti.$B$B<Iggy fa una smorfia di dolore.>$B$BMi aiuterai a completare la mia missione?', 0),
(11726, 'itIT', '<Iggy si tura il naso mentre svuota le sacche e ti parla con voce nasale.>$B$BOra mischierò queste spezie alle mie razioni d''emergenza per creare delle esche per i lupi.', 0),
(11728, 'itIT', '<Iggy si tura il naso e prende il microfilm.>$B$BBleah... be'', abbiamo rispettato l''articolo 8 comma 2 paragrafo B del protocollo d''emergenza e recuperato il microfilm. Nel protocollo però non c''è scritto che debba essere io a ripulire la pellicola.', 0),
(11798, 'itIT', '<Il vecchio Gnomo tira un pesante sospiro di sollievo.>$B$BÈ finita bene, dunque... ci hai salvati! Se non l''avessi fermato ora, chissà fin dove si sarebbe spinta la sua follia...$B$BTra la minaccia dei Draghi Blu e della Guerra del Nexus, per non parlare del Re dei Lich, l''ultima cosa di cui avevamo bisogno era una creazione dei Titani impazzita a piede libero!$B$BGrazie, $N!', 0),
(11873, 'itIT', '<Frizzapistone ascolta il tuo rapporto e sul suo volto si dipinge un''espressione sollevata.>$B$BAvrei dovuto andare con loro: avremmo potuto completare la missione senza perdere piloti.$B$BGiracode però ha ragione: è te che dobbiamo ringraziare per la riuscita della missione. I tuoi sforzi potrebbero fare la differenza nella guerra contro i Nerubiani.', 0),
(11876, 'itIT', '<L''Arcidruido Lathorius si asciuga le lacrime.>$B$BSono condannati. Ora che sono orfani e nessuno bada più a loro, sicuramente moriranno.', 0),
(11878, 'itIT', '<Odi una voce all''interno della testa. È Khu''nok.>$B$B$N, il tuo nome circola attraverso i venti. Hai fatto una grande cosa per la mia razza e per questo motivo ti consideriamo un alleato. Purtroppo il nostro tormento non avrà fine senza violenza e del sangue versato.$B$BIl prezzo della pace per i mammut è la morte di Kaw...', 0),
(11879, 'itIT', '<Lathorius prende l''alabarda dalle tue mani.>$B$BÈ quel che penso che sia?$B$B<Lathorius sogghigna.>$B$BFantastico! Eccezionale! Un altro Lacchè di Nesingwary sconfitto!', 0),
(11881, 'itIT', '<Fezzix esamina i componenti recuperati.>$B$BJenny è un po'' scossa, ma si riprenderà. Quanto ai componenti, sono un po'' più... malridotti di quel che mi aspettassi, ma dovrei riuscire a ricavarne qualcosa. Ma non considerarti congedato: mi servi ancora per ricostruire questa bellezza.', 0),
(11884, 'itIT', 'Almeno per qualche tempo, i rinoceronti avranno un po'' di pace. Grazie, $N.', 0),
(11892, 'itIT', 'Purtroppo Nesingwary è sparito. O forse non è mai stato qui...$B$B<Lathorius sospira.>$B$BQuel diavolo è viscido come un''anguilla, ma i suoi giorni sono contati. Lo troveremo, e allora...', 0),
(11893, 'itIT', '<Dorain annuisce.>$B$BBene. Questo dovrebbe bastare a dimostrare a Fezzix che ho ragione.', 0),
(11898, 'itIT', 'Ora che il Principe è stato sconfitto la presenza del Flagello nella Tundra Boreale ha subito un duro colpo, ma non voglio illudermi: torneranno presto alla carica, quindi devo preparare Durm a condurre gli abitanti del villaggio verso Foscogelo.$B$B<Il Capo Tribù scuote lentamente la testa.>$B$BNonostante tutti i contrasti avuti con Durm, mi fido del suo giudizio e delle sue capacità. Io sento di non poter abbandonare Taunka''le. Resterò qui a difenderla fino alla morte.', 0),
(11901, 'itIT', '<Quando ti avvicini al grano, il tuo stomaco comincia a torcersi. Il fetore è quasi insopportabile.>', 0),
(11909, 'itIT', '<La Madre Anziana tira un pesante sospiro di sollievo.>$B$BÈ finita, dunque... ci hai salvati! Se non l''avessi fermato ora, chissà fin dove ci avrebbe portato questo errore degli Gnomi?$B$BTra la minaccia dei Draghi Blu e della Guerra del Nexus, per non parlare del Re dei Lich, l''ultima cosa di cui avevamo bisogno era una creazione dei Titani impazzita a piede libero!$B$BGrazie, $N!', 0),
(11929, 'itIT', '<Madre Tauranook si asciuga le lacrime.>$B$BC''era un tempo in cui potevo passeggiare per questa Tundra e non vedevo altro che neve, ovunque guardassi.$B$BMa ora la neve ci ha abbandonati, segno che il nostro tempo qui sta per finire. Lasceremo Taunka''le e la Tundra Boreale con molti ricordi felici...$B$B<Madre Tauranook piange.>$B$BForse, un giorno, potremo tornare... e ritrovare la neve.', 0),
(11930, 'itIT', '<Wartook ti guarda, triste.>$B$BFoscogelo è perduta...', 0),
(11943, 'itIT', '<I pezzi da te raccolti cominciano a brillare nelle mani di Raelorasz.>$B$BÈ fatta.$B$BAvverto una forte presenza in questa prigione. Speriamo si riveli un alleato.', 0),
(11977, 'itIT', 'Quello che vedi qui è tutto ciò che resta dei Taunka della Tundra Boreale e di Dracombra. Sono un popolo allo sbando, ferito e condannato all''estinzione dal Flagello.$B$B<Zoccolo Chiaro scuote la testa.>$B$BSolo l''Orda può salvarli e guarire i loro spiriti. Noi ci prenderemo cura di loro ed essi in cambio rafforzeranno le file dell''Orda a Nordania.', 0),
(11979, 'itIT', 'Quello che vedi qui è tutto ciò che resta dei Taunka della Tundra Boreale e di Dracombra. Sono un popolo allo sbando, ferito e sull''orlo dell''estinzione.$B$B<Zoccolo Chiaro scuote la testa.>$B$BSolo l''Orda può salvarli e guarire i loro spiriti. Noi ci prenderemo cura di loro ed essi in cambio rafforzeranno le file dell''Orda a Nordania.', 0),
(11980, 'itIT', '<Roh''kill ti saluta.>$B$BHai difeso il nostro onore, $N. Tor''zin e io ti siamo molto riconoscenti per ciò che hai fatto!', 0),
(11981, 'itIT', '<Riferisci a Kurun il messaggio del Terrigeno caduto.>$B$BEssi combattono valorosamente, ma quello che ha detto è vero: non riusciremo a sconfiggere i Nani del Ferro di Thor Modan senza aiuto. I miei giganti e i Terrigeni combattono da molto tempo contro il male, ma non siamo abbastanza numerosi da vincere la battaglia per la conquista di Thor Modan. Ci aiuterai?', 0),
(11988, 'itIT', '<Torthen assembla frettolosamente i frammenti che gli hai portato.>$B$BNon è completa, ma dovrebbe permetterci di recuperare la maggior parte delle informazioni dalla placca.', 0),
(11990, 'itIT', '<Drakuru prende gli ingredienti e li mescola abilmente nell''ampolla.>$B$BDovrebbe funzionare, cumpà. Mo'' è il momento di mettersi al lavoro.', 0),
(11993, 'itIT', '<Torthen ti ascolta, mentre gli descrivi il contenuto delle Placche Runiche.>$B$BPer il martello di Madoran! Ha scoperto un''intera città dei Titani!$B$B"La culla della pietra e del ferro"...$B$B"Ulduar nascosta nella tempesta"...$B$BSecondo te che significa? Che sia il luogo da cui noi Nani proveniamo?$B$BDobbiamo seguirlo! Dobbiamo trovarlo!', 0),
(12002, 'itIT', '<Brugar ascolta il tuo rapporto.>$B$BSembra che la situazione si sia calmata per un po''. Inizieremo a cercare gli accessi alla rete di gallerie dei Nani del Ferro.', 0),
(12003, 'itIT', '<Brugar farfuglia una serie di parolacce in nanico.>$B$BNiente accessi? Nemmeno uno?$B$BCerto! Mica poteva essere facile! Be'', a questo punto non ci resta altra scelta che entrare in territorio nemico. I miei ragazzi non torneranno mai al loro vero lavoro!', 0),
(12010, 'itIT', '<Un rapido esame del corpo rivela che l''Ispettore è morto già da un po'' di tempo. Frughi nella sacca e trovi le sue note manoscritte.>', 0),
(12014, 'itIT', '<Brugar legge il rapporto.>$B$BNon mi piace per niente. Anche se riuscissimo a scavare delle gallerie per superare la barricata, non è detto che non crollino di nuovo. Alcune di queste zone non vengono usate da generazioni. Dobbiamo riferire la cattiva notizia al Capitano Gryan.', 0),
(12029, 'itIT', 'Ottimo lavoro!$B$B<Per un istante, Mack scoppia in una risata folle.>$B$BAh... e andiamo, è shtato divertente... hic!', 0),
(12036, 'itIT', 'Quella dannata depressione deve essere collegata direttamente ad Azjol-Nerub. La situazione è peggiore di quel che credessi.$B$B<Juktok si ferma un attimo a riflettere.>$B$BTrovare e distruggere... queste saranno le nostre prossime mosse.', 0),
(12041, 'itIT', '<Il Supremo Agmar osserva il documento.>$B$BÈ quello che penso? Con le informazioni contenute in queste pagine SPAZZEREMO VIA gli Anub''ar!$B$BMi hai reso un grande servizio portandomi questo documento, $N. Forse ti permetteremo di assistere, o addirittura di partecipare, allo scontro finale ad Angrathar! LOK''TAR!', 0),
(12042, 'itIT', '<Povero Goblin sfortunato! Deve aver scoperto il Cuore degli Antichi mentre scavava in zona. Sicuramente non ne conosceva la natura. In mezzo a tutto quel caos, nessuno ha prestato attenzione al Cuore.>', 0),
(12056, 'itIT', '<Gort solleva la testa e la fissa.>$B$BTe l''avevo detto che ti avremmo trovato...$B$BEcco la tua ricompensa, $c. Con questo abbiamo un problema in meno di cui preoccuparci.', 0),
(12060, 'itIT', 'Quella che mi stai descrivendo è una proiezione... dell''Arcanomicon!$B$B<L''Arcimaga nasconde in fretta la propria preoccupazione dietro un''espressione impassibile.>$B$BL''Arcanomicon è la mappa di tutti gli incroci fra le linee di faglia magiche del mondo. Lo Stormo dei Draghi Blu la sta usando per trovare e distruggere le ancore delle linee di faglia e rispedire il potere magico al Nexus.$B$BLa domanda è: come mai il sentiero della distruzione conduce a est mentre dovrebbe volgere verso ovest?', 0),
(12061, 'itIT', 'Quella che mi stai descrivendo è una proiezione... dell''Arcanomicon!$B$B<L''Arcimago nasconde in fretta la propria preoccupazione dietro un''espressione impassibile.>$B$BL''Arcanomicon è la mappa di tutti gli incroci fra le linee di faglia magiche del mondo. Lo Stormo dei Draghi Blu la sta usando per trovare e distruggere le ancore delle linee di faglia e rispedire il potere magico al Nexus.$B$BLa domanda è: come mai il sentiero della distruzione conduce a est mentre dovrebbe volgere verso ovest?', 0),
(12064, 'itIT', 'Sì, questi andranno bene.$B$B<Banthok armeggia con i frammenti della chiave.>$B$BEcco qua, $c. Con questa chiave potremo liberare mio padre dalla Prigione di Anub''ar.', 0),
(12067, 'itIT', 'Oh no... e dire che ti avevamo mandato laggiù per ucciderla.$B$B<Il Comandante scuote la testa e sospira.>$B$BMi dispiace. Farò in modo che questa lettera giunga subito a suo padre, l''Arcimago Malin di Roccavento. Non preoccuparti, tu non c''entri niente... non potevi saperlo.$B$BCerca di dimenticare tutto quanto, $N.', 0),
(12071, 'itIT', '<Valnok ti saluta.>$B$BTu saresti quello di cui ho sentito tanto parlare?', 0),
(12072, 'itIT', '<Valnok ti saluta.>$B$BE con questo li abbiamo annientati anche in aria! Presto potresti essere convocato ad Angrathar, eroe!', 0),
(12085, 'itIT', 'Ahahahaha... davvero commovente.$B$B<Avverti un chiaro senso di soddisfazione nella risata del Supremo.>$B$BChe ti avevo detto? Traditori! Tuttavia, conoscevo Deino e so che è una Troll d''onore!$B$BFarò in modo che sappia la fine che ha fatto suo fratello. Ed eviterò di dirle che sei stato tu a ucciderlo.$B$B<Agmar ti fissa con uno sguardo freddo.>$B$BOra sei mio, $c!', 0),
(12098, 'itIT', '<Trovi il cadavere del Comandante dei Cacciatori di Maghi.>$B$B<A giudicare dal suo aspetto e dalle condizioni delle forze intorno a lui, non sono morti affogati. Piuttosto, quando hanno evocato il punto di focalizzazione, sono stati sorpresi dall''attacco degli elementali che vivevano nel lago.>$B$B<A quanto pare, i Cacciatori di Maghi sono i responsabili della loro stessa morte.>', 0),
(12104, 'itIT', '<Soar solleva la fiala al cielo e ne esamina il contenuto.>$B$BOra rimane solo una cosa da fare.', 0),
(12106, 'itIT', '<Trovi il cadavere del Comandante dei Cacciatori di Maghi.>$B$B<A giudicare dal suo aspetto e dalle condizioni delle forze intorno a lui, non sono morti affogati. Piuttosto, quando hanno evocato il punto di focalizzazione, sono stati sorpresi dall''attacco degli elementali che vivevano nel lago.>$B$B<A quanto pare, i Cacciatori di Maghi sono i responsabili della loro stessa morte.>', 0),
(12107, 'itIT', 'COSA?!?$B$B<L''immagine davanti a te si distorce per un attimo mentre l''Arcimaga cerca di ricomporsi.>$B$BMa certo... avremmo dovuto capirlo subito che miravano a questo. Presto, non c''è tempo da perdere.$B$BBisogna avvertire la Lega dei Draghi!', 0),
(12110, 'itIT', 'COSA?!?$B$B<L''immagine davanti a te si distorce per un attimo mentre l''Arcimago cerca di ricomporsi.>$B$BMa certo... avremmo dovuto capirlo subito che miravano a questo. Presto, non c''è tempo da perdere.$B$BBisogna avvertire la Lega dei Draghi!', 0),
(12123, 'itIT', 'Sei stata molto coraggiosa a portarci questa informazione. Anch''io mi ero chiesta come mai lo Stormo Blu avesse deciso di attaccare il tempio. Ora sappiamo che stanno usando enormi quantità della stessa magia che vedono come una minaccia per Azeroth.$B$B<La regina scuote la testa quasi in segno di rassegnazione.>$B$BÈ da ipocriti, ma purtroppo è così. Se Malygos non tornerà sui suoi passi, non abbiamo altra scelta che rispondere al loro attacco.', 0),
(12124, 'itIT', 'Sei stato molto coraggioso a portarci questa informazione. Anch''io mi ero chiesta come mai lo Stormo Blu avesse deciso di attaccare il tempio. Ora sappiamo che stanno usando enormi quantità della stessa magia che vedono come una minaccia per Azeroth.$B$B<La regina scuote la testa quasi in segno di rassegnazione.>$B$BÈ da ipocriti, ma purtroppo è così. Se Malygos non tornerà sui suoi passi, non abbiamo altra scelta che rispondere al loro attacco.', 0),
(12126, 'itIT', '<Koltira spalanca gli occhi.>$B$BNon ho parole. Hai sconfitto un Cavaliere della Morte di Arthas. Evidentemente non eri da solo, ma poco importa...', 0),
(12130, 'itIT', '<Raegar si asciuga la fronte con il dorso della mano.>$B$BOh, no. Sarà più difficile di quanto pensassi. Questi pezzi non hanno un numero seriale, vero?$B$BNon c''è mai uno Gnomo, quando serve...', 0),
(12131, 'itIT', '<Raegar prende le batterie dalle tue mani.>$B$BBene! Ora dovremmo essere pronti.', 0),
(12136, 'itIT', '<Gort prende il tomo dalle tue mani e inizia a leggerlo.>$B$BCOSA? Non è possibile. Conosco diversi di questi Orchi da anni!$B$BLasciami da solo, $N. Ho parecchio lavoro da fare e molti traditori da giustiziare.$B$BPrendi questo oggetto per il disturbo. Oggi hai reso un grande servizio all''Orda.', 0),
(12153, 'itIT', 'Ha funzionato?!?$B$B<Raegar si schiarisce la voce.>$B$BVoglio dire... certo che ha funzionato! Incredibile!$B$BNegli anni a venire, gli Iniziati della Lega degli Esploratori ascolteranno la storia di come Raegar Spaccafronte, $N e un Golem assemblato alla peggio sconfissero il Thane di Dun Argol!', 0),
(12154, 'itIT', '<Raegar annuisce soddisfatto.>$B$BNon sopporto di veder sprecare degli esplosivi. Inoltre, abbiamo sicuramente rallentato i nemici.', 0),
(12171, 'itIT', '<Palena legge la nota.>$B$BSalirai sul mio ippogrifo più veloce, $r! Queste informazioni vanno consegnate immediatamente al Gran Comandante Sventradraghi!', 0),
(12174, 'itIT', '<Il Gran Comandante legge la lettera e poi l''accartoccia.>$B$BSai dove si trovano ora le persone contenute in questa lista? Da'' un''occhiata fuori, vicino al cancello d''ingresso. Sono quelli che penzolano dalle arcate.$B$BEsche per i Ghoul...', 0),
(12183, 'itIT', '<Consegni l''uniforme a Kilian.>$B$BDovrebbe andare bene. Non ho tempo di ricamare "$N" su una toppa. Comunque, quando avremo finito di camuffarti, chiunque ti vedrà da vicino si convincerà che fai parte dei sovrintendenti.', 0),
(12206, 'itIT', 'COSA?!? Non è possibile! Avevamo perfezionato il morbo, rendendolo mortale al cento per cento.$B$B<La speziale si contorce le mani, visibilmente preoccupata, quindi continua con tono arrabbiato.>$B$BÈ davvero molto strano. Dammi quella fiala, $c. Non passerò alla storia come la speziale che ha mandato tutto in malora!', 0),
(12221, 'itIT', '<Il Dottor Malefious esamina il contenuto del pacco.>$B$BFantastico! È tutto secondo le previsioni!$B$BEcco la tua ricompensa, $N. Non dire a nessuno ciò che hai fatto o visto. Questo progetto è segretissimo e deve rimanere tale.', 0),
(12226, 'itIT', 'Dovrebbe bastare...$B$B<Anderhol piega gli steli, raccogliendo il denso liquido in una fiala.>$B$BEcco fatto: ora diamo fuoco alle polveri.', 0),
(12230, 'itIT', '<Il Guardiamorte si frega le mani in attesa.>$B$BEccellente. Queste bombe ci torneranno utili!$B$BNon ti hanno dato problemi lungo il tragitto, vero? Alcune di essere sembrano alquanto instabili. Anche se sono un Non Morto, ci tengo alle mie ossa!', 0),
(12235, 'itIT', '<Urik indica un grifone.>$B$BHai mai cavalcato uno di questi? È facile. Basta che sali e gli dici dove vuoi andare.', 0),
(12239, 'itIT', 'Hai notizie dalla Maestra delle Spie?$B$B<L''agente si guarda intorno per essere certa che nessuno la stia guardando mentre posa la pala.>$B$BFammi vedere questi piani.', 0),
(12249, 'itIT', '<Gli occhi della Druida stremata fissano un punto all''orizzonte dietro di te. Risanare Vordrassil ha evidentemente prosciugato le sue energie. Ha lasciato un pacco, in attesa del tuo ritorno.>', 0),
(12251, 'itIT', '<Halford ti saluta.>$B$BGli abitanti sono già tornati tutti al lavoro? È una magnifica notizia, soldato! Ricostruiremo e fortificheremo questa città in men che non si dica. A breve, i rinforzi saranno pronti per raggiungere Ser Domadraghi al Cancello dell''Ira.$B$BC''è però ancora parecchio da fare prima di poter correre in aiuto di Bolvar.', 0),
(12252, 'itIT', 'Sapeva tutto questo? Chi diavolo è questo Gran Ammiraglio Zefiro di cui parlava?$B$B<Il Gran Esecutore borbotta tra sé e sé di quanto odi le sorprese.>$B$BA ogni modo, meglio saperlo che dover tirare a indovinare. Spero tu gli abbia lasciato... ehm, il mio marchio.', 0),
(12254, 'itIT', 'Una benedizione scritta di recente sul retro del breviario, hai detto?$B$B<L''agente guarda da dietro le tue spalle mentre vai all''ultima pagina.>$B$BDannazione! Quella è la calligrafia del Gran Abate! La riconoscerei ovunque.', 0),
(12269, 'itIT', '<Leoric prende i tesserini da te.>$B$BLi consegnerò al nostro archivista e informerò le famiglie dei minatori.$B$BC''è ancora molto da fare se vogliamo vincere qui e al Cancello dell''Ira. Ser Domadraghi conta su di noi.', 0),
(12274, 'itIT', 'Che diavolo è successo?!?$B$BChe vuol dire che si è buttato di sotto? Sei sicuro di non averlo spinto tu?$B$B<L''agente ti fissa socchiudendo gli occhi.>$B$BVa bene. È evidente che qui sta succedendo qualcosa di molto più grande di quel che pensassimo.', 0),
(12276, 'itIT', '<C''è una nota stretta nella mano di Slinkin.>$B$BMi hanno inseguito in un vicolo cieco. Per ora mi sono nascosto, ma sanno che sono qui. Non passerà molto tempo prima che mi trovino.$B$BI minatori lavorano incessantemente per estrarre il Minerale Strano che alimenta le macchine da guerra del Flagello. Parlano molto. La lingua della morte mi confonde, ma sono riuscito a individuare i suoni e le frasi più usate. Il termine "Yogg-Saron" viene pronunciato con grande disprezzo, e di solito è seguito da violente esplosioni. Chiamano il minerale "saronite". Che vorrà dire?', 0),
(12285, 'itIT', 'Adesso vediamo se riescono a riportarla in vita senza la testa!$B$B<La risata del Gran Esecutore attira diverse occhiate furtive.>$B$BSono un po'' preoccupato dal fatto che ti sei lasciato scappare questo Gran Ammiraglio, ma sei comunque l''eroe del giorno, $N!$B$BEcco la tua ricompensa... te la sei guadagnata!', 0),
(12290, 'itIT', '<Orik prende l''Erbanotte e comincia a preparare l''elisir.>$B$BNon ci vorrà molto, $N.', 0),
(12291, 'itIT', '<Gli occhi di Orik si riempiono di lacrime.>$B$BNessuno di loro sa come andò veramente! Credono che Arthas sia un grande eroe, mentre in realtà fu proprio lui a ordinare che le navi venissero incendiate. Fu Arthas che ci lasciò a morire in questa landa gelata!$B$B<Orik piange.>$B$BNon tutti i soldati della flotta del Principe morirono per il freddo invernale. All''epoca ero appena un ragazzo, e mi fu data la possibilità di combattere il Flagello... per salvare le nostre case da una sicura distruzione. Accettai, $N.', 0),
(12292, 'itIT', 'È chiusa, vero? Sembra essere una cassa piuttosto ordinaria.$B$B<Il Tenente Dumont scuote la cassa, producendo un suono legnoso.>$B$BLasciamo perdere il contenuto. Se grazie a questa cassa otterremo un vantaggio contro l''Orda, non m''interessa nemmeno se contiene la cura per la Piaga.', 0),
(12301, 'itIT', '<Orik ti sorride.>$B$BHai compiuto una buona azione oggi, $N. Centinaia di anime perse ora sono state redente, grazie a te.', 0),
(12303, 'itIT', '<Il quartiermastro resta senza fiato, poi socchiude gli occhi mentre ti studia per un attimo.>$B$BSpero che tu non ti sia intascato parte di queste ricchezze. Non sarai mica così avido quando c''è di mezzo il destino di Venefica, vero?$B$BAvevo comunque deciso di dartene una parte, come ricompensa. Non è molto, ma in tempi come questi dobbiamo fare tutti dei sacrifici.', 0),
(12305, 'itIT', '<Zelig sorride.>$B$BSono io a essere in debito con te, eroina. Orik è come un fratello per me. Hai cambiato la sua vita e dato nuova speranza a innumerevoli altre.', 0),
(12307, 'itIT', '<Katja si allontana da te, nervosamente.>$B$BGrazie, $N. Non hai della Strozzalupo con te, vero? Sai... ehm... sono allergica a quell''erbaccia.', 0),
(12309, 'itIT', 'Diavolo, laggiù è un disastro! L''ultima volta sono riuscito a mettermi in salvo appena in tempo. Per questo ho chiesto aiuto al Gran Comandante.$B$B<Durkon ti osserva.>$B$BTu hai lo sguardo del pazzo, $r. Meglio così, perché ci vuole un pazzo per fare ciò che sto per chiederti.', 0),
(12319, 'itIT', '<Halford spalanca gli occhi.>$B$BOggi il destino ci sorride, $N. Conosco la persona giusta a cui mostrare questo tomo.', 0),
(12320, 'itIT', 'Forse, se motivato a dovere, Godfrey ci dirà quello che sa sul tomo.$B$B<Hallard si volta verso il Sindaco Godfrey.>$B$BDico bene, sindaco?', 0),
(12463, 'itIT', '<Trovi un diario sul corpo di Fregabarba.>$B$BGiorno uno:$B$BHanno trascinato cadaveri attraverso la galleria fino alla Stanza dell''Imbalsamazione per fare degli esperimenti. Ci sono un numero infinito di corpi in questo mausoleo. Quelli che non riescono a rianimare vengono trasformati in Costrutti d''Ossa.$B$BGiorno due:$B$BTemo che questo Lich, Thel''zan, nasconda un segreto oscuro. Chi è? Una volta era... uno di noi?$B$BGiorno tre: Ho scoperto dove si trova il Filatterio del Lich. È...$B$B<Le restanti pagine sono strappate.>', 0),
(12464, 'itIT', 'Sbarazzarci di Abbendis è stata una decisione difficile, ma necessaria. In un''altra vita, probabilmente avremmo combattuto fianco a fianco.$B$B<La voce del comandante si affievolisce mentre si ferma a riflettere un momento prima di proseguire.>$B$BSono un po'' preoccupato per questo Gran Ammiraglio di cui mi hai parlato. Hai detto che si chiama Barean Zefiro? Non posso credere che sia ancora vivo. Deve essere molto vecchio. Ci occuperemo di lui più tardi.$B$BNel frattempo, credo tu ti sia guadagnata una ricompensa è un po'' di meritato riposo.', 0),
(12465, 'itIT', '<Ambo legge le pagine del diario recuperate.>$B$BC''è una notizia buona e una cattiva. Quale vuoi sapere prima?$B$BOh, al diavolo, cominciamo con quella buona: se riusciamo a trovare il Filatterio di Thel''zan, possiamo annientarlo. La notizia cattiva è che il Filatterio è in possesso di un Dragone del Gelo di dimensioni generose.', 0),
(12470, 'itIT', 'Hai visto Nozdormu? Non è possibile.$B$B<Cromie si ferma a riflettere un attimo sulle tue parole.>$B$BIn realtà, si tratta di un''ottima notizia! Non sapevamo dove si fosse diretto il Signore del Tempo, né quando fosse partito. Sapevamo soltanto che era sparito per occuparsi di questioni della massima urgenza.$B$BAnche se il capo dello Stormo dei Draghi dell''Infinito non è stato rivelato, hai scoperto che Nozdormu è vivo e vegeto e che sta combattendo contro di loro!$B$BGrazie, $N. Ci rivedremo presto!', 0),
(12489, 'itIT', 'Ah! Non s''incontra spesso un completo sconosciuto nel mezzo della giungla.$B$BSei un tirapiedi dei Druidi mandato per "porre fine alle mie malvagie azioni"? Be'', buona fortuna!$B$B<Hemet ride di gusto e batte sulla sua arma.>$B$BLo immaginavo! Appena ci saremo occupati di quei cani della S.P.R. & Co., potrai tranquillamente unirti alla caccia. Ci sono parecchie prede in giro.', 0),
(12542, 'itIT', 'A pochi passi da qui si trova l''Impero dei Drakkari.$B$B<Valus indica verso est.>$B$BPer migliaia di anni i Drakkari sono rimasti isolati, preferendo vivere entro i confini delle loro città tempio e delle Ziggurat. È stata una sorpresa aver trovato tutto in rovina. Più avanti, oltre le scale che portano a Zul''drak, il Forte di Drak''Tharon giace in macerie. Tutta la prima fila di Zul''drak è andata distrutta...$B$BPerché il Flagello ha atteso fino a ora per attaccare?', 0),
(12543, 'itIT', '<L''oracolo esamina le zanne.>$B$BApproviamo! Le Ossa di Nozronn parleranno a $N!', 0),
(12556, 'itIT', '<Hemet esamina il corno.>$B$BChe trofeo strabiliante di un animale magnifico! $N, ho sentito parlare di prede ancora più grandi e feroci che si aggirano nella zona settentrionale del bacino e vorrei che ci aiutassi a braccarle.', 0),
(12560, 'itIT', '<Debaar prende le Felcesabbia e inizia ad avvolgerle attorno al tuo corpo.>$B$BSì, dovrebbe funzionare. Non muoverti! Ti trasformerò in un cespuglio.', 0),
(12565, 'itIT', '<Se Zim''Abwa potesse muovere la sua faccia, Zim''Abwa ti sorriderebbe.>', 0),
(12567, 'itIT', '<Senti l''approvazione di Zim''Abwa. Capisci che Zim''Abwa vuole altre offerte!>', 0),
(12569, 'itIT', '<Debaar ascolta mentre racconti come il travestimento non abbia funzionato.>$B$BCosa significa che il nostro piano non ha funzionato come doveva?$B$BBe'', ti fa onore il fatto che tu l''abbia ucciso comunque. Guarda quelle fauci! Hemet sarà fiero delle nostre imprese. Questo crocolisco era davvero un mostro.', 0),
(12592, 'itIT', 'Ti arrendi già?$B$B<Drostan resta a bocca aperta quando gli dici di aver già ucciso tutte le tue prede.>$B$BImpossibile! Come hai fatto? Io ne ho uccisi solo 58. Per un pelo!$B$BMa è giusto così. Ti ho sottovalutato, $N, e tu hai vinto in maniera onesta.', 0),
(12612, 'itIT', '<Il cadavere è arso completamente. Nelle vicinanze sembrano esserci i resti di diversi barili di polvere da sparo.>', 0),
(12618, 'itIT', '<La Madre della Prosperità irradia su di te la sua approvazione.>', 0),
(12631, 'itIT', 'Conosco bene oggetti come questo.$B$B<Stefan ti guarda negli occhi.>$B$BPare proprio che tu sia stata scelta, $N.', 0),
(12633, 'itIT', 'Conosco bene oggetti come questo.$B$B<Stefan ti guarda negli occhi.>$B$BPare proprio che tu sia stato scelto, $N.', 0),
(12644, 'itIT', '<Malasbronza scuote il barile.>$B$BQui dentro c''è sicuramente qualcosa, la domanda da un milione di monete d''oro è se riuscirai a berlo. Non andartene, sarai responsabile anche del processo di assaggio.', 0),
(12656, 'itIT', '<Zim''Rhuk proietta nella tua mente l''immagine di te che vieni schiacciato da uno dei suoi Guardiani. Forse dovresti provare a compiacerlo con altre offerte.>', 0),
(12681, 'itIT', '<Colvin guarda con ammirazione gli artigli che gli hai portato.>$B$BDovrebbero essere più che sufficienti. Secondo i Gorloc, più un artiglio è contorto, più potere racchiude. Sono certo che l''Arcimago ricaverà un bel gruzzolo da questa spedizione.', 0),
(12697, 'itIT', 'Hai combattuto con tenacia per invadere il Reame del Falciatore... Aspetta.$B$B<Gothik guarda i suoi appunti.>$B$BTi faccio le mie scuse, $r. Le vecchie abitudini sono dure a morire.$B$BTi manda Valanar? Immagino dunque che tu sia una persona in gamba.$B$BHo un dono per quei cani Scarlatti che affretterà sicuramente il loro lavoro nelle miniere.', 0),
(12699, 'itIT', 'Eccellente!', 0),
(12708, 'itIT', 'Mo'' ci penseranno due volte prima di mettersi a fare altri di chelli cosi. Tremo solo all''idea di dover lottare contro nu esercito di chelle bestie.$B$B<La Domatrice si fa un attimo pensierosa.>$B$BCredo che sarebbe come affrontare le infinite ondate del Flagello.', 0),
(12724, 'itIT', '<Orbaz sfoglia il programma.>$B$BQuesti sciocchi si sono tenuti impegnati! Ci sono percorsi delle pattuglie a nord, a sud, a est e a ovest, ma nessun accenno alle rotte dei loro corrieri. Aspetta un attimo. Cos''è questo? Somiglia al percorso di una pattuglia a ovest, proveniente dalle Terre Infette Occidentali. Questa pattuglia passerà di qui oggi! Ho bisogno di tempo per mettere a punto un piano.', 0),
(12725, 'itIT', 'Sei stato uno sciocco a venire qui. Io ho fallito. Mi avrebbero dovuto lasciare a morire... ora rischiamo di essere uccisi entrambi.$B$B<Koltira scuote la testa.>$B$BSiamo Cavalieri della Morte del Flagello. Questo va contro i patti della Fratellanza Oscura.$B$BThassarian, stupido che non sei altro!', 0),
(12727, 'itIT', 'Darò in pasto la testa di questo mostro ai Ghoul!$B$B<Thassarian getta la testa nella stanza sul retro.>$B$BKoltira è riuscito a fuggire?$B$B<Thassarian si interrompe.>$B$BNe ero sicuro. Quelle mura non possono trattenerlo.$B$BÈ tempo di vendicarci.', 0),
(12754, 'itIT', '<Orbaz legge il messaggio.>$B$BGli eserciti di Valsalda e Tirisfal andranno incontro a un massacro.$B$B<Orbaz sorride.>$B$BOra, per quanto riguarda la seconda parte del piano, dovrai consegnare questo messaggio nelle mani del Gran Generale Abbendis. È a questo che ti servono i vestiti...', 0),
(12755, 'itIT', '<Il Gran Generale Abbendis legge il messaggio.>$B$BMaledizione! Gli eserciti di Valsalda e Tirisfal non devono raggiungere Nuova Avalon! Il Flagello li massacrerà tutti.', 0),
(12756, 'itIT', '<Orbaz sfoglia le pagine del diario.>$B$BChe sciocchezze! Questa sarebbe l''"Alba Cremisi?"$B$BStanno navigando incontro alla morte! Concentriamoci sugli eserciti invasori.', 0),
(12813, 'itIT', '<Il Cavaliere della Morte Draenei ti fissa con il suo sguardo gelido come una tomba. Un leggero ghigno si dipinge sul suo volto.>$B$BPreparerò dell''altra Pozione domani. Fino ad allora, stammi bene.', 0),
(12821, 'itIT', 'Ottimo!$B$B<Sul viso di Ricket appare un ghigno feroce.>$B$BChe la distruzione abbia inizio!', 0),
(12857, 'itIT', '<Il Capo Malartiglio piange.>$B$BAvevo Mantorabbioso da quando era un cucciolo. Triste giorno per Malartiglio. Prima i Troll attaccano Malartiglio, poi i Troll rendono Mantorabbioso cattivo. Malartiglio non avrà mai più niente a che fare con i Troll!', 0),
(12883, 'itIT', 'Se è lo stesso Drakuru del Forte di Drak''Tharon, allora abbiamo bisogno di aiuto dall''esterno.$B$BI Cavalieri della Morte di Acherus sono accampati nelle vicinanze, probabilmente stanno seguendo la stessa scia lasciata dal Flagello che ha attirato qui la Crociata d''Argento. Siccome metà del nostro esercito è bloccata al Bastione d''Argento per combattere contro i Drakkari, non ci resta che unire le forze con i Cavalieri della Spada d''Ebano.$B$B<Lantinga borbotta a bassa voce.>$B$BSperavo di non dover più vedere quelle canaglie dopo la Cappella della Luce...', 0),
(12884, 'itIT', '<Stefan legge la missiva, quindi la accartoccia e la getta nel fuoco.>$B$BNotizie vecchie. Ancora una volta la Crociata d''Argento è in ritardo per la festa. Stiamo seguendo Drakuru dai Colli Bradi. È già pronto per essere sradicato.', 0),
(12894, 'itIT', 'Andava tutto bene, almeno fino all''attacco del Flagello. Hanno preso Dargath, Gerk e Burr e hanno distrutto il nostro veicolo. Sai chi guidava l''attacco?$B$B<MacKellar scuote il capo.>$B$BNavarius...$B$BSembra che l''intera area sia una specie di fabbrica del Flagello. Siamo in mezzo a un campo minato di non morti!', 0),
(12943, 'itIT', '<Il Duca Lankral annuisce in segno d''approvazione per il tuo successo.>$B$BAffrontiamo dei nemici che ci sovrastano! Non solo in statura, ma anche numericamente. Se vogliamo vincere la battaglia per la Corona di Ghiaccio, dobbiamo essere più furbi di loro!$B$BLa morte di Ufrang ci ha regalato un vantaggio a Jotunheim. Vediamo se riusciamo a sfruttarlo come si deve.', 0),
(12977, 'itIT', 'Un senso di pace e soddisfazione ti pervade, sapendo che le tormentate anime di Impietrituono ora riposano in pace.', 0),
(12980, 'itIT', '<Bruor ascolta mentre gli racconti cos''hai scoperto nell''officina.>$B$BDunque i padroni di Valduran gli hanno dato questo oscuro metallo affinché costruisca un''arma gigantesca? Vorrà usarla per sferrare l''attacco finale contro di noi! Dobbiamo fermarlo, prima che la completi e scateni la sua potenza.', 0),
(12981, 'itIT', '<Provi un senso di appagamento quando capisci che i tuoi sforzi continuano a rafforzare i rinnovati legami tra Thorim e i Figli di Hodir.>', 0),
(12993, 'itIT', '<Spaccaroccia esamina i documenti e sgrana gli occhi.>$B$BNon avevo idea che i Forgiatuono fossero capaci di qualcosa del genere! I nostri uomini non avranno alcuna possibilità contro questo Colosso, se sarà completato. Per fortuna sembra che manchi ancora una parte fondamentale.', 0),
(12994, 'itIT', '<Mentre rimetti la catena attorno al collo della Madre dell''Antro, questa ti lecca il viso soddisfatta.>', 0),
(13003, 'itIT', '<È finita.>$B$B<Hai affrontato una morte certa e ne sei uscito vincitore.>$B$B<Uccidendo una creatura così potente solo con le tue forze, hai portato un grande onore a Dun Niffelem!>', 0),
(13006, 'itIT', '<Nell''istante in cui ricopri l''elmo con un sottile strato di olio, il ghiaccio scompare e la superficie inizia a brillare.>', 0),
(13043, 'itIT', 'Hai scoperto e sventato le macchinazioni del dottore.$B$B<La Megera controllata dalla Banshee sorride e posa delicatamente una mano sulla tua spalla.>$B$BSarà un bel grattacapo per il Re dei Lich, ma possiamo fare di meglio.', 0),
(13044, 'itIT', '<Penumbrius annuisce.>$B$BLa mia razza vi aiuterà. Combatteremo insieme contro il Re dei Lich e le sue legioni di non morti.', 0),
(13045, 'itIT', 'Arthas... Si getta a capofitto nella battaglia, irruento e incauto. L''abbiamo trovato con la guardia abbassata.$B$B<Il Gran Signore Tirion Fordring fa una pausa, perdendosi per un istante nei suoi pensieri.>$B$BRafforzeremo le difese per fare fronte alla crisi.$B$B$N, come te la cavi con un cannone?', 0),
(13060, 'itIT', '<Olut fa una smorfia.>$B$BTutto bene? Ma è stata un''entrata di grande effetto.$B$BSei qui per aiutarci a trovare un ingresso per la Corona di Ghiaccio? Come vedi, la nostra prima incursione da quelle parti non è finita molto bene. Credo sarebbe meglio tentare di penetrare da un''altra parte.', 0),
(13081, 'itIT', '<Mentre ti avvicini al Naaru, un leggero tintinnio risuona nella tua testa.>$B$BSo perché sei qui.', 0),
(13084, 'itIT', '<Il Duca ti guarda per un momento e annuisce.>$B$BHai inflitto un terribile trauma mentale ai Vrykul di Jotunheim. Quello è il luogo in cui si sono risvegliati la prima volta: quindi è un posto molto importante per loro, secondo solo a Ymirheim.$B$BDevi mantenere alta la pressione, mentre io respingo gli attacchi del Re dei Lich alla Volta.', 0),
(13104, 'itIT', 'La mia conoscenza delle tattiche del Flagello non ha eguali.$B$B<Il Guardiano d''Ebano ti scruta.>$B$BPrima della battaglia per la Cappella della Luce, io e i miei Cavalieri servivamo il Re dei Lich. Le sue gelide grinfie controllavano ogni nostra azione. La Luce dell''Alba ha cambiato tutto.', 0),
(13117, 'itIT', '<Racconti al Cavaliere Oscuro ciò che hai scoperto all''Altare dell''Evocazione.>$B$BLo sospettavo. Non possiamo permetterlo. La nostra priorità è distruggere gli Altari dell''Evocazione e solo successivamente affrontare ciò che il Flagello ha già creato.', 0),
(13119, 'itIT', '<Il Cavaliere Oscuro Arly annuisce.>$B$BBene. Ora possiamo dedicarci a bloccare il resto dell''Officina della Carne.', 0),
(13120, 'itIT', '<Il Cavaliere Oscuro Arly chiude gli occhi e si concentra su qualcosa in lontananza.>$B$BCon gli occhi della Morte, osservo i nostri nemici. Grazie a questa conoscenza, potremo annientarli.', 0),
(13134, 'itIT', '<Appena arrivi al cospetto del Cavaliere Oscuro, vieni accolto da una risata oscura e cupa.>$B$B$N, odori di vittoria... e questa è davvero un''ottima notizia.', 0),
(13136, 'itIT', '<Olakin maneggia con cautela i frammenti di metallo.>$B$BLi hai trovati su tutti i Ghoul laggiù? Ho combattuto numerose volte contro il Flagello, ma non ho mai visto nulla del genere.', 0),
(13152, 'itIT', '<Il Cavaliere Oscuro Arly ride cupa.>$B$BLa fine giusta per il "buon" dottore, non credi?', 0),
(13157, 'itIT', 'Ci attende un viaggio lungo e pericoloso verso i Cancelli della Rocca della Corona di Ghiaccio. Io e i Soldati della Crociata d''Argento vogliamo ringraziarti per tutto ciò che hai fatto. Riposiamo più sereni, sapendo che combatti al nostro fianco in questo luogo maledetto.$B$B<Il Gran Signore Tirion Fordring ti saluta militarmente.>', 0),
(13174, 'itIT', 'Vediamo un po'' cosa abbiamo qui...$B$B<Keritose si immerge nella lettura delle carte per un attimo, senza scoprire nulla che non sapesse già. Poi all''improvviso trova ciò che stava cercando.>$B$BMalykriss! La Rocca Ignobile. Arthas non ha preso bene la perdita dei suoi Cavalieri della Morte. Non so di preciso cosa intenda farsene di tutta quella Saronite, ma ho il sospetto che stia escogitando qualcosa.$B$BQuel ragazzo non è abituato a perdere.', 0),
(13188, 'itIT', '<Anduin volge lo sguardo in lontananza.>$B$BProprio così, vecchio amico... sangue e onore.$B$B<Anduin ti fissa.>$B$BSe non fosse per questa lettera da parte di Tirion, ti avrei già fatto incatenare. Sei salvo solo grazie all''appoggio di uno dei più grandi Paladini che siano mai esistiti.$B$BCollaboreremo insieme contro il Flagello e contro il Re dei Lich!$B$BGLORIA ALL''ALLEANZA!', 0),
(13211, 'itIT', '<Il Crociato Olakin Sainrith ascolta in solenne silenzio il tuo rapporto.>$B$BNon è la sepoltura che meritavano, ma meglio che niente. Soprattutto, meglio per chi è ancora vivo! Grazie, $N.', 0),
(13214, 'itIT', 'Sangue fresco!$B$B<Il Cavaliere della Morte Vrykul sputa a terra ai tuoi piedi.>$B$BCredete tutti di possedere ciò che serve per combattere in questo luogo.$B$BSiete nulla in confronto alla potenza dei Vrykul e del Flagello!$B$BEppure, avete sconfitto sei cadaveri incapaci... quindi dovete possedere qualche tipo di abilità. In ogni caso, probabilmente non vi basterà per superare la prossima sfida.', 0),
(13224, 'itIT', '<Korm ti saluta militarmente.>$B$BChe siano maledetti il Flagello e l''Alleanza! Hork era uno degli Orchi migliori. Ma lo vendicheremo! Per Malogrido e per l''Orda!', 0),
(13225, 'itIT', '<Il Capitano Bartlett ti saluta.>$B$BEra un soldato eccezionale. Che siano maledetti l''Orda e il Flagello!', 0),
(13228, 'itIT', 'Hanno visto l''Alleanza assaltare il Portale e l''hanno attaccata alle spalle...$B$B<Dopo una breve pausa, Korm scoppia in una risata.>$B$BCOSÌ si comporta l''ORDA!$B$BSe non fosse per lei, i vermi dell''Alleanza ora avrebbero il Portale!$B$BGrazie al suo coraggio, abbiamo guadagnato del tempo prezioso.', 0),
(13260, 'itIT', '<Koltira ti squadra dall''alto in basso.>$B$B$c, spero per il tuo bene che tu sia all''altezza dell''impresa.', 0),
(13285, 'itIT', '<Boktar annuisce soddisfatto mentre gli racconti di come hai aiutato Brann a recuperare i pezzi della Chiave di Pietra.>$B$BBrann potrebbe rivelarsi l''alleato di cui abbiamo bisogno per scoprire cosa sta succedendo a Ulduar. Hai fatto bene ad aiutarlo. Ci serve tutto l''aiuto possibile contro questo Loken e i suoi servitori Nani del Ferro.', 0),
(13306, 'itIT', '<Koltira annuisce brevemente.>$B$BBene. Non saranno una gran protezione, ma è meglio che niente. Se i Comandanti del Flagello sanno quello che fanno, quella Porta è un collo di bottiglia perfetto. Dobbiamo ottenere il controllo della maggior parte possibile di area circostante.', 0),
(13320, 'itIT', '<Avvitachiodi versa il contenuto della bottiglia nel suo Analizzatore Tetraidroparticolare.>$B$BQuesto è un semplice conglomerato riuscito male...', 0),
(13328, 'itIT', '<Koltira prende i frammenti di cristallo dalle tue mani e parla a voce bassa.>$B$BMe li ricordo...$B$BPossono far crollare facilmente gli uomini deboli. Hai compiuto un gran gesto, rimuovendo questa minaccia.', 0),
(13329, 'itIT', '<Koltira ascolta il tuo rapporto.>$B$BBene. I miei ingegneri mescoleranno più acido possibile, prima di preparaci ad attaccare in massa Corp''rethar.', 0),
(13332, 'itIT', '<Thassarian annuisce.>$B$BBene. Non saranno una gran protezione, ma è meglio che niente. Se i Comandanti del Flagello sanno quello che fanno, quella Porta è un collo di bottiglia perfetto. Dobbiamo ottenere il controllo della maggior parte possibile di area circostante.', 0),
(13335, 'itIT', '<Thassarian ascolta attentamente, mentre descrivi il buon esito della prova.>$B$BQuindi l''acido ha funzionato! Bene. Ci servirà, quando il nostro esercito dovrà scontrarsi con un gran numero di Razziatori.', 0),
(13339, 'itIT', '<Thassarian prende i frammenti di cristallo dalle tue mani e parla a voce bassa.>$B$BMe li ricordo...$B$BPossono far crollare facilmente gli uomini deboli. Hai compiuto un gran gesto, rimuovendo questa minaccia.', 0),
(13355, 'itIT', '<Ramartiglio versa il contenuto della bottiglia nel suo Analizzatore Particolare.>$B$BAhh... so cos''è!', 0),
(13372, 'itIT', 'I più antichi membri dello Stormo dei Draghi Blu possiedono queste chiavi. Solo a loro vengono affidate dal loro signore, Malygos.$B$BÈ ciò che aspettavamo per colpire l''Aspetto della Magia!$B$B<La Regina dei Draghi ti osserva per un attimo.>$B$BNon sei in grado di usare la Chiave per accedere all''Iride Focalizzante, ma posso infondergli parte del mio potere, abbastanza perché tu riesca a usarla per aprire l''Iride di una minima parte.$B$BSarà sufficiente per attirare l''ira di Malygos!', 0),
(13375, 'itIT', 'I più antichi membri dello Stormo dei Draghi Blu possiedono queste chiavi. Solo a loro vengono affidate dal loro signore, Malygos.$B$BÈ ciò che aspettavamo per colpire l''Aspetto della Magia!$B$B<La Regina dei Draghi ti osserva per un attimo.>$B$BNon sei in grado di usare la Chiave per accedere all''Iride Focalizzante, ma posso infondergli parte del mio potere, abbastanza perché tu riesca a usarla per aprire l''Iride di una minima parte.$B$BSarà sufficiente per attirare l''ira di Malygos!', 0),
(13389, 'itIT', '<L''oggetto pulsante è ricoperto da uno spesso strato di ghiaccio. Brilla in maniera strana sott''acqua.>', 0),
(13393, 'itIT', '<Il Demolitore ha visto giorni migliori, ma la struttura non ha subito danni permanenti. Le parti che hai recuperato dovrebbero bastare a rimetterlo in funzione, almeno provvisoriamente.>', 0),
(13600, 'itIT', '<Il Maresciallo prende la Lama di Drak''Mar che gli porgi.>$B$BUn''arma splendida e perfettamente bilanciata. Mi sarà utile nel prossimo incontro.', 0),
(13604, 'itIT', '<Il disco di platino combacia alla perfezione con la console. Un raggio di luce bianca ne scansiona la superficie che inizia a ruotare.>', 0),
(13654, 'itIT', '<La Crociata Rhydalla esamina il contenuto della borsa con espressione disgustata.>$B$BÈ tutto qui, $N: il veleno che ha ucciso Lorien, una collezione di coltelli, torce e olio. Nessuno ha un motivo per possedere queste cose, qui, e nessuno scudiero agirebbe in questo modo senza aver ricevuto degli ordini dal suo Cavaliere. Abbiamo trovato il nostro assassino, $N, ma per chi lavora?', 0),
(13663, 'itIT', '<La Crociata Rhydalla impallidisce quando legge gli ordini.>$B$BQuesto può significare solo una cosa, $N. Il Cavaliere Nero fa parte del Culto dei Dannati ed è stato inviato da Arthas a portare scompiglio durante il torneo!$B$BIl Cavaliere Nero si è dimostrato un combattente temibile... se vuoi affrontarlo, dovrai dare fondo a tutte le tue capacità. Una volta ottenuto il titolo di Campione, torna da me e troveremo il modo di sconfiggerlo.', 0),
(13742, 'itIT', '<La Gran Campionessa prende la Lama di Drak''Mar che le porgi.>$B$BUn''arma splendida e perfettamente bilanciata. Mi sarà utile nel prossimo incontro.', 0),
(13747, 'itIT', '<Ambrose prende la Lama di Drak''Mar che gli porgi.>$B$BUn''arma splendida e perfettamente bilanciata. Mi sarà utile nel prossimo incontro.', 0),
(13753, 'itIT', '<Il Gran Campione prende la Lama di Drak''Mar che gli porgi.>$B$BUn''arma splendida e perfettamente bilanciata. Mi sarà utile nel prossimo incontro.', 0),
(13758, 'itIT', '<Jaelyne prende la Lama di Drak''Mar che le porgi.>$B$BUn''arma splendida e perfettamente bilanciata. Mi sarà utile nel prossimo incontro.', 0),
(13817, 'itIT', '<Il disco di platino combacia alla perfezione con la console. Un raggio di luce bianca ne scansiona la superficie che inizia a ruotare.>', 0),
(13889, 'itIT', '<Il Cucciolo di Malapelle sembra soddisfatto del lauto pasto che gli hai procurato, ma non c''è modo di sapere quando avrà di nuovo fame.>', 0),
(13903, 'itIT', '<Il Cucciolo di Malapelle ti sorride per un secondo e si mette a dormire.>', 0),
(14016, 'itIT', '<La Crociata Rhydalla si incupisce.>$B$BPensi che abbiano organizzato tutto? Immagino non importi, ma non mi piace l''idea di averli potuti aiutare. Qualunque cosa stia succedendo, dobbiamo intervenire.', 0),
(14077, 'itIT', '<Narasi prende il libro di preghiere che le porgi.>$B$BGrazie. Il libro è un dono del Confessore Paletress in persona. Sarebbe onorata di sapere che lo hai utilizzato per donare pace ai morti.', 0),
(14144, 'itIT', '<Girana accetta il libro di preghiere.>$B$BGrazie. Abbiamo avuto delle divergenze con i Crociati, ma durante la mia permanenza qui ho imparato molto dal Confessore Paletress.', 0),
(14443, 'itIT', '<Caladis prende l''elsa e la rigira lentamente fra le mani.>$B$BMi sembra familiare, come se dovessi conoscerne le origini. Hai detto di averla trovata nella Rocca? Davvero curioso...$B$BForse quei pochi in grado di forgiare una lama come questa potranno dirti qualcosa di più.', 0),
(14457, 'itIT', '<L''Arcanista Tybalin esamina gli ordini recuperati.>$B$BL''Agente che hai intercettato avrebbe dovuto trasportare il Tomo della Lega dei Draghi alla Corona di Ghiaccio, dopo essersi incontrato con un certo Magistro Hathorel nel Santuario dei Predatori del Sole. $N, è la nostra unica possibilità di recuperare quel libro! Ma non sarà facile...', 0),
(24442, 'itIT', '<Mariel prende gli ordini, il cristallo della veggenza e li esamina entrambi.>$B$BOttimo lavoro, $N, e complimenti per la prontezza di riflessi. Il furto di questa cianfrusaglia non li rallenterà a lungo, ma ci hai fatto guadagnare il tempo necessario per avvisare i capi dell''Orda e dell''Alleanza degli attacchi imminenti.', 0),
(24454, 'itIT', '<Caladis prende il pesante libro e inizia a scorrerlo.>$B$BSapevo che i simboli sulla lama erano familiari! L''arma è stata sicuramente forgiata dai draghi e donata a una delle razze mortali. Ma quale sarà la lama? E com''è finita nella Corona di Ghiaccio?', 0),
(24536, 'itIT', 'Grazie mille! Vieni qui e diamo un''occhiata.$B<Prende lo strumento dalle tue mani e ci giocherella per un po''.>$BPessime notizie...', 0),
(24547, 'itIT', '<Il Gran Signore Mograine ti scruta in silenzio per un momento.>$B$B$r, hai superato ammirevolmente questa parte della missione.$B$BPrega affinché il fato continui ad arriderti...', 0),
(24554, 'itIT', '<Myralion prende l''Elsa dalle tue mani e la scruta.>$B$BProviene dalla Rocca? E che ci faceva, lì? La lama non è un manufatto del Flagello.$B$BSono poche le creature di Azeroth in grado di forgiare armi di questa qualità. Dobbiamo andare a parlare con loro e scoprire se possono aiutarci a identificarla.', 0),
(24557, 'itIT', '<Il Magistro Hathorel esamina gli ordini recuperati.>$B$BL''Agente che hai intercettato avrebbe dovuto trasportare il Tomo della Lega dei Draghi alla Corona di Ghiaccio, dopo essersi incontrato con un certo Arcanista Tybalin nell''Enclave d''Argento. $N, dobbiamo impadronirci di quel libro prima che esca dalla città. Bisogna agire in fretta.', 0),
(24558, 'itIT', '<Myralion prende il pesante libro e inizia a scorrerlo.>$B$BI simboli sulla lama mi erano familiari e ora capisco perché: si tratta sicuramente di una Lama dei Draghi, donata a una delle razze mortali. Ma quale lama, precisamente? E com''è finita nella Corona di Ghiaccio?', 0),
(24655, 'itIT', 'Grazie mille! Vieni qui e diamo un''occhiata.$B<Prende lo strumento dalle tue mani e ci giocherella per un po''.>$BPessime notizie...', 0)
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(351, 'itIT', '<Hai appena scoperto i rottami di... una gallina robot? La voce gracchiante torna a farsi sentire dall''interno dell''uovo:>$B$B"Sì! Ottimo lavoro! È proprio il mio robot teleguidato. Secondo i miei sensori, ha bisogno di una partenza assistita per tornare alla Baia del Bottino per essere riparato. Piazza il trasmettitore al suo interno. Non serve altro!".', 0),
(941, 'itIT', '<Questa fioriera contiene un terreno speciale creato da Denalan.>', 0),
(2278, 'itIT', '<La voce del Guardiano della Pietra rimbomba nelle remote stanze del tuo essere:>$B$B"Devi prima soddisfare i requisiti per l''assimilazione dei dati dei dischi di Norgannon. Quando li avrai raggiunti, ti sarà permesso di ottenere una versione portatile dei dati conservati. Ti prego di assicurarti di aver prima esaminato tutte le informazioni contenute in questo archivio".', 0),
(2945, 'itIT', '<Sul dispositivo gnomesco davanti a te c''è una placca con su scritto: "Lavatutto 5200". La funzione della macchina, da quello che si evince leggendo le indicazioni sotto la placca, è rimuovere lo sporco dagli oggetti. La macchina ha una fessura per le monete. Ce ne vogliono tre d''argento per avviarla, una volta sistemato l''oggetto da pulire al suo interno.>$B$B<Pare sia proprio quello che ci vuole per ripulire l''Anello Sudicio che hai trovato in precedenza!>', 0),
(2951, 'itIT', '<Sembra che la macchina abbia bisogno di un Oggetto Sudicio da pulire e di tre monete d''argento per funzionare. Solo così la Lavatutto 5200 si metterà in moto...>', 0),
(4601, 'itIT', '<Sembra che la macchina abbia bisogno di un Oggetto Sudicio da pulire e di tre monete d''argento per funzionare. Solo così la Lavatutto 5200 si metterà in moto...>', 0),
(9349, 'itIT', 'Hai già preso le uova?$B$B<Lo stomaco di Legassi brontola dall''impazienza.>', 0),
(9569, 'itIT', '<La Vendicatrice Aalesia, visibilmente preoccupata per via del problema posto dai Satiri, ha lo sguardo perso nel vuoto.>$B$BHai attaccato il capo dei Satiri come ti avevo chiesto?', 0),
(9570, 'itIT', '<Kurz grugnisce verso di te.>', 0),
(9623, 'itIT', '<Torallius si sistema la benda sull''occhio per guardarti meglio.>$B$BQuesto è il meglio che possiamo offrire alla Mano di Argus?', 0),
(9648, 'itIT', 'Ricorda, ciascuno dei funghi che ti ho chiesto si trova in una determinata area di Brumacremisi.', 0),
(9698, 'itIT', '<Velen sorride.>$B$BSalve $N. Ti stavo aspettando.', 0),
(9794, 'itIT', '<Gli occhi di Kialon sono sospettosi.>$B$BNon ti conosco, $R. Abbiamo qualche affare in sospeso?', 0),
(9800, 'itIT', '<L''Elementalista Lo''ap ti mostra i suoi pugni e scuote la testa con disapprovazione.>$B$BPugni di Ogre...', 0),
(9897, 'itIT', 'Kristen è molto carina... <Tossisce> ...a condividere le sue pelli, non trovi?', 0),
(9911, 'itIT', '<La Guardiana sgrana gli occhi dalla sorpresa.>$B$BDove hai preso quella... cosa?', 0),
(9934, 'itIT', '<Garrosh non batte ciglio di fronte all''offerta.>', 0),
(10004, 'itIT', '<Sal''salabim si gratta la testa.>$B$B[Demoniaco] Ik il romath sardon.', 0),
(10037, 'itIT', '<Seth ti strattona il mantello.>$B$BHai trovato le anguille? Le hai trovate?', 0),
(10280, 'itIT', '<Il tintinnio musicale della parlata naruu ti riempie la mente.>$B$B$R, sento che hai con te un oggetto di grande potere. Cosa mi hai portato?', 0),
(10289, 'itIT', 'Un rapporto di Orion? Dammelo, presto!$B$B<Corrucciato, il Generale Krakork scorre rapidamente il documento stropicciato.>$B$BMaledizione, è esattamente come temevamo! Orion e i suoi guerrieri potrebbero venire sopraffatti da un momento all''altro!', 0),
(10334, 'itIT', '<La mucca ti guarda con diffidenza, ma non si muove.>', 0),
(10528, 'itIT', '<Ar''tor fluttua senza vita di fronte a te.>', 0),
(10541, 'itIT', '<Una singola lacrima riga la guancia di Oronok.>', 0),
(10547, 'itIT', '<Tobias aggrotta un sopracciglio.>$B$BCardosangue? Mai sentito parlare... Sei dei Pacificatori? Sai che dovresti dirmelo se lo fossi... Ho dei diritti!', 0),
(10597, 'itIT', '<Consegni i materiali a Gulmok.>', 0),
(10704, 'itIT', '<La voce di A''dal vibra melodiosamente nella tua mente.>$B$BHai fatto ritorno. Hai portato i due frammenti della chiave di Arcatraz?', 0),
(10793, 'itIT', '<Il Gran Generale Auralion fluttua al centro del cristallo.>$B$BCosa... Cosa ci fai qui?', 0),
(11288, 'itIT', '<Ares è svenuto.>', 0),
(11422, 'itIT', '<Il Vecchio Pinnagelo ti scruta con uno dei suoi occhi da pesce lesso. Ovviamente, cerca di capire se hai portato il tridente di suo figlio.>', 0),
(11448, 'itIT', '<Stanwad borbotta.>', 0),
(11603, 'itIT', '<Il vecchio ti guarda con uno sguardo spento.>', 0),
(12031, 'itIT', '<L''Anziano Mana''loa ti guarda dentro e sente che non hai ancora portato a termine il tuo incarico.>', 0),
(12048, 'itIT', '<Borus getta a terra i suoi attrezzi.>$B$BQuesti non servono a niente!', 0),
(12057, 'itIT', '<Gort solleva un sopracciglio.>', 0),
(12067, 'itIT', 'Una lettera per me?$B$B<Il comandante ti osserva per un attimo.>$B$BA quanto pare no... Immagino siano brutte notizie.', 0),
(12085, 'itIT', 'Cos''è questa? Hai intenzione di spedire una lettera?$B$BTutta la posta deve passare prima da me. Ci sono spie e traditori in mezzo a noi!$B$B<Il Supremo ti osserva e ti chiedi se ha intenzione di farti uccidere sul posto.>$B$BD''accordo, ma fa'' presto. E ti avverto... se non dovesse piacermi quello che c''è scritto, ti darò in pasto ai miei worg.$B$B<Agmar ride mentre Gar''mak e Lak''tuk ti guardano come se fossi il loro prossimo pasto.>', 0),
(12097, 'itIT', '<Gort solleva un sopracciglio.>$B$BGià di ritorno?', 0),
(12239, 'itIT', '<L''agente ti guarda, poi ti fa cenno di allontanarti.>$B$BNon far saltare la mia copertura, $c!', 0),
(12565, 'itIT', '<Zim''Abwa guarda imperturbabile a nord e a sud.>', 0),
(12699, 'itIT', 'Hai trovato nulla, $N?', 0),
(12756, 'itIT', '<Orbaz ride.>$B$BCos''è questo? Un libro da colorare per bambini?', 0),
(12801, 'itIT', '<Il Gran Signore Mograine annuisce.>', 0),
(12981, 'itIT', '<Un bagliore luminoso avvolge l''incudine.>', 0),
(13006, 'itIT', '<Il gelo continua ad avvolgere l''Elmo mentre lo guardi. Inoltre, si stanno iniziando a formare dei ghiaccioli sui bordi...>', 0),
(13393, 'itIT', '<Il Demolitore è pesantemente danneggiato.>', 0),
(13604, 'itIT', '<La console inizia a rombare e il ricettacolo rotondo si apre.>', 0),
(13817, 'itIT', '<La console inizia a rombare e il ricettacolo rotondo si apre.>', 0),
(13818, 'itIT', '<Le luci brillanti della console scansionano ripetutamente la superficie di vetro, come se si aspettassero un comando di qualche tipo.>', 0)
