-- Quest 9859 itIT Objectives: the AzerothCore text names Harold Lane, not Hemet Nesingwary
UPDATE `quest_template_locale` SET `Objectives` = REPLACE(`Objectives`, 'Hemet Nesingwary', 'Harold Lane')
WHERE `ID` = 9859 AND `locale` = 'itIT' AND `Objectives` LIKE '%Hemet Nesingwary%';

-- Import the quest texts extracted from Wowhead (WotLK = Retail English): fill only the empty fields of quest_template_locale itIT

ON DUPLICATE KEY UPDATE `Title` = IF(IFNULL(`Title`, '') = '', VALUES(`Title`), `Title`);

ON DUPLICATE KEY UPDATE `Details` = IF(IFNULL(`Details`, '') = '', VALUES(`Details`), `Details`);

ON DUPLICATE KEY UPDATE `EndText` = IF(IFNULL(`EndText`, '') = '', VALUES(`EndText`), `EndText`);

ON DUPLICATE KEY UPDATE `ObjectiveText1` = IF(IFNULL(`ObjectiveText1`, '') = '', VALUES(`ObjectiveText1`), `ObjectiveText1`);

ON DUPLICATE KEY UPDATE `ObjectiveText2` = IF(IFNULL(`ObjectiveText2`, '') = '', VALUES(`ObjectiveText2`), `ObjectiveText2`);

ON DUPLICATE KEY UPDATE `ObjectiveText3` = IF(IFNULL(`ObjectiveText3`, '') = '', VALUES(`ObjectiveText3`), `ObjectiveText3`);

ON DUPLICATE KEY UPDATE `ObjectiveText4` = IF(IFNULL(`ObjectiveText4`, '') = '', VALUES(`ObjectiveText4`), `ObjectiveText4`);

-- Import the quest reward texts extracted from Wowhead (WotLK = Retail English): fill only the empty RewardText of quest_offer_reward_locale itIT
ON DUPLICATE KEY UPDATE `RewardText` = IF(IFNULL(`RewardText`, '') = '', VALUES(`RewardText`), `RewardText`);

-- Import the quest request items texts extracted from Wowhead (WotLK = Retail English): fill only the empty CompletionText of quest_request_items_locale itIT
ON DUPLICATE KEY UPDATE `CompletionText` = IF(IFNULL(`CompletionText`, '') = '', VALUES(`CompletionText`), `CompletionText`);
